  (385, 'Jirachi', 3, 'steel', 'psychic', 'Wish Pokémon', 3, 11, 'Generations have believed that any wish written on a note on its head will come true when it awakens.', null, null),
  (386, 'Deoxys', 3, 'psychic', null, 'DNA Pokémon', 17, 608, 'DNA from a space virus mutated and became a Pokémon. It appears where auroras are seen.', null, null),
  (387, 'Turtwig', 4, 'grass', null, 'Tiny Leaf Pokémon', 4, 102, 'Photosynthesis occurs across its body under the sun. The shell on its back is actually hardened soil.', null, null),
  (388, 'Grotle', 4, 'grass', null, 'Grove Pokémon', 11, 970, 'A Grotle that lives in the forest is said to have its own secret springwater.', 387, 'Level 18'),
  (389, 'Torterra', 4, 'grass', 'ground', 'Continent Pokémon', 22, 3100, 'Ancient people imagined that beneath the ground, a gigantic Torterra dwelled.', 388, 'Level 32'),
  (390, 'Chimchar', 4, 'fire', null, 'Chimp Pokémon', 5, 62, 'The gas made in its belly burns from its rear end. The fire burns weakly when it feels sick.', null, null),
  (391, 'Monferno', 4, 'fire', 'fighting', 'Playful Pokémon', 9, 220, 'A bigger fire on its tail and a brighter blue pattern on its face means its rank in its pack is higher.', 390, 'Level 14'),
  (392, 'Infernape', 4, 'fire', 'fighting', 'Flame Pokémon', 12, 550, 'It tosses its enemies around with agility. It uses all its limbs to fight in its own unique style.', 391, 'Level 36'),
  (393, 'Piplup', 4, 'water', null, 'Penguin Pokémon', 4, 52, 'It doesn’t like to be taken care of. It’s difficult to bond with since it won’t listen to its Trainer.', null, null),
  (394, 'Prinplup', 4, 'water', null, 'Penguin Pokémon', 8, 230, 'It lives a solitary life. Its wings deliver wicked blows that can snap even the thickest of trees.', 393, 'Level 16'),
  (395, 'Empoleon', 4, 'water', 'steel', 'Emperor Pokémon', 17, 845, 'It avoids unnecessary disputes, but it will decimate anything that threatens its pride.', 394, 'Level 36'),
  (396, 'Starly', 4, 'normal', 'flying', 'Starling Pokémon', 3, 20, 'They flock around mountains and fields, chasing after bug Pokémon. Their singing is noisy and annoying.', null, null),
  (397, 'Staravia', 4, 'normal', 'flying', 'Starling Pokémon', 6, 155, 'They maintain huge flocks, although fierce scuffles break out between various flocks.', 396, 'Level 14'),
  (398, 'Staraptor', 4, 'normal', 'flying', 'Predator Pokémon', 12, 249, 'When Staravia evolve into Staraptor, they leave the flock to live alone. They have sturdy wings.', 397, 'Level 34'),
  (399, 'Bidoof', 4, 'normal', null, 'Plump Mouse Pokémon', 5, 200, 'It lives in groups by the water. It chews up boulders and trees around its nest with its incisors.', null, null),
  (400, 'Bibarel', 4, 'normal', 'water', 'Beaver Pokémon', 10, 315, 'It busily makes its nest with stacks of branches and roots it has cut up with its sharp incisors.', 399, 'Level 15'),
  (401, 'Kricketot', 4, 'bug', null, 'Cricket Pokémon', 3, 22, 'When its antennae hit each other, it sounds like the music of a xylophone.', null, null),
  (402, 'Kricketune', 4, 'bug', null, 'Cricket Pokémon', 10, 255, 'By allowing its cry to resonate in the hollow of its belly, it produces a captivating sound.', 401, 'Level 10'),
  (403, 'Shinx', 4, 'electric', null, 'Flash Pokémon', 5, 95, 'The extension and contraction of its muscles generates electricity. Its fur glows when it’s in trouble.', null, null),
  (404, 'Luxio', 4, 'electric', null, 'Spark Pokémon', 9, 305, 'By gathering their tails together, they collectively generate powerful electricity from their claws.', 403, 'Level 15'),
  (405, 'Luxray', 4, 'electric', null, 'Gleam Eyes Pokémon', 14, 420, 'Luxray’s ability to see through objects comes in handy when it’s scouting for danger.', 404, 'Level 30'),
  (406, 'Budew', 4, 'grass', 'poison', 'Bud Pokémon', 2, 12, 'When it feels the sun’s warm touch, it opens its bud to release pollen. It lives alongside clear pools.', null, null),
  (407, 'Roserade', 4, 'grass', 'poison', 'Bouquet Pokémon', 9, 145, 'Its sweet aroma attracts prey. Then it spews poison. The more toxic it is, the sweeter its aroma.', 315, 'Shiny Stone'),
  (408, 'Cranidos', 4, 'rock', null, 'Head Butt Pokémon', 9, 315, 'Cranidos toughen up their already rock-hard heads by headbutting one another.', null, null),
  (409, 'Rampardos', 4, 'rock', null, 'Head Butt Pokémon', 16, 1025, 'Its skull withstands impacts of any magnitude. As a result, its brain never gets the chance to grow.', 408, 'Level 30'),
  (410, 'Shieldon', 4, 'rock', 'steel', 'Shield Pokémon', 5, 570, 'It was generated from a fossil dug out of a layer of clay that was older than anyone knows. It has a sturdy face.', null, null),
  (411, 'Bastiodon', 4, 'rock', 'steel', 'Shield Pokémon', 13, 1495, 'When attacked, they form a wall. Their rock-hard faces serve to protect them from the attacks.', 410, 'Level 30'),
  (412, 'Burmy', 4, 'bug', null, 'Bagworm Pokémon', 2, 34, 'It covers itself with a cloak to shelter from the cold. When it’s hot, its cloak is thinner.', null, null),
  (413, 'Wormadam', 4, 'bug', 'grass', 'Bagworm Pokémon', 5, 65, 'It is said that a Wormadam that evolves on a cold day will have a thicker cloak.', 412, 'Level 20 (female)'),
  (414, 'Mothim', 4, 'bug', 'flying', 'Moth Pokémon', 9, 233, 'It flutters around at night and steals honey from the Combee hive.', 412, 'Level 20 (male)'),
  (415, 'Combee', 4, 'bug', 'flying', 'Tiny Bee Pokémon', 3, 55, 'At night, Combee sleep in a group of about a thousand, packed closely together in a lump.', null, null),
  (416, 'Vespiquen', 4, 'bug', 'flying', 'Beehive Pokémon', 12, 385, 'It raises grubs in the holes in its body. It secretes pheromones to control Combee.', 415, 'Level 21 (female)'),
  (417, 'Pachirisu', 4, 'electric', null, 'EleSquirrel Pokémon', 4, 39, 'It’s one of the kinds of Pokémon with electric cheek pouches. It shoots charges from its tail.', null, null),
  (418, 'Buizel', 4, 'water', null, 'Sea Weasel Pokémon', 7, 295, 'It inflates its flotation sac, keeping its face above water in order to watch for prey movement.', null, null),
  (419, 'Floatzel', 4, 'water', null, 'Sea Weasel Pokémon', 11, 335, 'With its flotation sac inflated, it can carry people on its back. It deflates the sac before it dives.', 418, 'Level 26'),
  (420, 'Cherubi', 4, 'grass', null, 'Cherry Pokémon', 4, 33, 'It evolves by sucking the energy out of the small ball where it had been storing nutrients.', null, null),
  (421, 'Cherrim', 4, 'grass', null, 'Blossom Pokémon', 5, 93, 'During times of strong sunlight, its bud blooms, its petals open fully, and it becomes very active.', 420, 'Level 25'),
  (422, 'Shellos', 4, 'water', null, 'Sea Slug Pokémon', 3, 63, 'Its shape and coloration vary, depending on its habitat.', null, null),
  (423, 'Gastrodon', 4, 'water', 'ground', 'Sea Slug Pokémon', 9, 299, 'When its natural enemy attacks, it oozes purple fluid and escapes.', 422, 'Level 30'),
  (424, 'Ambipom', 4, 'normal', null, 'Long Tail Pokémon', 12, 203, 'They live on large trees. They are said to communicate by connecting their tails to those of others.', 190, 'Level up knowing Double Hit'),
  (425, 'Drifloon', 4, 'ghost', 'flying', 'Balloon Pokémon', 4, 12, 'It is whispered that any child who mistakes Drifloon for a balloon and holds on to it could wind up missing.', null, null),
  (426, 'Drifblim', 4, 'ghost', 'flying', 'Blimp Pokémon', 12, 150, 'It can generate and release gas within its body. That’s how it can control the altitude of its drift.', 425, 'Level 28'),
  (427, 'Buneary', 4, 'normal', null, 'Rabbit Pokémon', 4, 55, 'You can tell how it feels by the way it rolls its ears. When it’s scared, both ears are rolled up.', null, null),
  (428, 'Lopunny', 4, 'normal', null, 'Rabbit Pokémon', 12, 333, 'It sheds its fur twice a year. Its winter fur is soft and fluffy.', 427, 'Friendship'),
  (429, 'Mismagius', 4, 'ghost', null, 'Magical Pokémon', 9, 44, 'Its cries sound like incantations to torment the foe. It appears where you least expect it.', 200, 'Dusk Stone'),
  (430, 'Honchkrow', 4, 'dark', 'flying', 'Big Boss Pokémon', 9, 273, 'It is merciless by nature. It is said that it never forgives the mistakes of its Murkrow followers.', 198, 'Dusk Stone'),
  (431, 'Glameow', 4, 'normal', null, 'Catty Pokémon', 5, 39, 'When it’s happy, Glameow demonstrates beautiful movements of its tail, like a dancing ribbon.', null, null),
  (432, 'Purugly', 4, 'normal', null, 'Tiger Cat Pokémon', 10, 438, 'It would claim another Pokémon’s nest as its own if it finds a nest sufficiently comfortable.', 431, 'Level 38'),
  (433, 'Chingling', 4, 'psychic', null, 'Bell Pokémon', 2, 6, 'It emits high-frequency cries that people can’t hear. Once it starts, it can cry for an awfully long time.', null, null),
  (434, 'Stunky', 4, 'poison', 'dark', 'Skunk Pokémon', 4, 192, 'The foul fluid from its rear is so revolting that it can make people feel queasy up to a mile and a quarter away.', null, null),
  (435, 'Skuntank', 4, 'poison', 'dark', 'Skunk Pokémon', 10, 380, 'It attacks by spraying a repugnant fluid from its tail, but the stench dulls after a few squirts.', 434, 'Level 34'),
  (436, 'Bronzor', 4, 'steel', 'psychic', 'Bronze Pokémon', 5, 605, 'Ancient people believed that the pattern on Bronzor’s back contained a mysterious power.', null, null),
  (437, 'Bronzong', 4, 'steel', 'psychic', 'Bronze Bell Pokémon', 13, 1870, 'Ancient people believed that petitioning Bronzong for rain was the way to make crops grow.', 436, 'Level 33'),
  (438, 'Bonsly', 4, 'rock', null, 'Bonsai Pokémon', 5, 150, 'In order to adjust the level of fluids in its body, it exudes water from its eyes. This makes it appear to be crying.', null, null),
  (439, 'Mime Jr.', 4, 'psychic', 'fairy', 'Mime Pokémon', 6, 130, 'In an attempt to confuse its enemy, it mimics the enemy’s movements. Then it wastes no time in making itself scarce!', null, null),
  (440, 'Happiny', 4, 'normal', null, 'Playhouse Pokémon', 6, 244, 'It carefully carries a round, white rock that it thinks is an egg. It’s bothered by how curly its hair looks.', null, null),
  (441, 'Chatot', 4, 'normal', 'flying', 'Music Note Pokémon', 5, 19, 'It mimics the cries of other Pokémon to trick them into thinking it’s one of them. This way they won’t attack it.', null, null),
  (442, 'Spiritomb', 4, 'ghost', 'dark', 'Forbidden Pokémon', 10, 1080, 'It was formed by uniting 108 spirits. It has been bound to the Odd Keystone to keep it from doing any mischief.', null, null),
  (443, 'Gible', 4, 'dragon', 'ground', 'Land Shark Pokémon', 7, 205, 'It nests in horizontal holes warmed by geothermal heat. Foes who get too close can expect to be pounced on and bitten.', null, null),
  (444, 'Gabite', 4, 'dragon', 'ground', 'Cave Pokémon', 14, 560, 'As it digs to expand its nest, it habitually digs up gems that it then hoards in its nest.', 443, 'Level 24'),
  (445, 'Garchomp', 4, 'dragon', 'ground', 'Mach Pokémon', 19, 950, 'Its body is covered in fine scales that reduce drag, enabling it to fly at high speeds.', 444, 'Level 48'),
  (446, 'Munchlax', 4, 'normal', null, 'Big Eater Pokémon', 6, 1050, 'It conceals food under the long fur on its body. It carts around this food stash and swallows it without chewing.', null, null),
  (447, 'Riolu', 4, 'fighting', null, 'Emanation Pokémon', 7, 202, 'They communicate with one another using their auras. They are able to run all through the night.', null, null),
  (448, 'Lucario', 4, 'fighting', 'steel', 'Aura Pokémon', 12, 540, 'It’s said that no foe can remain invisible to Lucario, since it can detect auras. Even foes it could not otherwise see.', 447, 'Friendship (day)'),
  (449, 'Hippopotas', 4, 'ground', null, 'Hippo Pokémon', 8, 495, 'It shrouds itself in sand to ward off germs. It travels easily through the sands of the desert.', null, null),
  (450, 'Hippowdon', 4, 'ground', null, 'Heavyweight Pokémon', 20, 3000, 'It brandishes its gaping mouth in a display of fearsome strength. It raises vast quantities of sand while attacking.', 449, 'Level 34'),
  (451, 'Skorupi', 4, 'poison', 'bug', 'Scorpion Pokémon', 8, 120, 'It burrows under the sand to lie in wait for prey. Its tail claws can inject its prey with a savage poison.', null, null),
  (452, 'Drapion', 4, 'poison', 'dark', 'Ogre Scorpion Pokémon', 13, 615, 'It attacks people and Pokémon that cross the desert. This has only furthered its bad reputation.', 451, 'Level 40'),
  (453, 'Croagunk', 4, 'poison', 'fighting', 'Toxic Mouth Pokémon', 7, 230, 'Fluid squeezed from its finger, albeit poisonous, is a significant ingredient in remedies for lower-back pain.', null, null),
  (454, 'Toxicroak', 4, 'poison', 'fighting', 'Toxic Mouth Pokémon', 13, 444, 'Swaying and dodging the attacks of its foes, it weaves its flexible body in close, then lunges out with its poisonous claws.', 453, 'Level 37'),
  (455, 'Carnivine', 4, 'grass', null, 'Bug Catcher Pokémon', 14, 270, 'It walks around on its tentacles in search of a tree branch where it can dangle down and ambush prey.', null, null),
  (456, 'Finneon', 4, 'water', null, 'Wing Fish Pokémon', 4, 70, 'Swimming and fluttering its two tail fins, it looks like a Beautifly. At night, the patterns on its tail fins softly shine.', null, null),
  (457, 'Lumineon', 4, 'water', null, 'Neon Pokémon', 12, 240, 'Lumineon swimming in the darkness of the deep sea look like stars shining in the night sky.', 456, 'Level 31'),
  (458, 'Mantyke', 4, 'water', 'flying', 'Kite Pokémon', 10, 650, 'When it swims close to the surface of the ocean, people aboard ships are able to observe the pattern on its back.', null, null),
  (459, 'Snover', 4, 'grass', 'ice', 'Frost Tree Pokémon', 10, 505, 'During cold seasons, it migrates to the mountain’s lower reaches. It returns to the snow-covered summit in the spring.', null, null),
  (460, 'Abomasnow', 4, 'grass', 'ice', 'Frost Tree Pokémon', 22, 1355, 'It lives a quiet life on mountains that are perpetually covered in snow. It hides itself by whipping up blizzards.', 459, 'Level 40'),
  (461, 'Weavile', 4, 'dark', 'ice', 'Sharp Claw Pokémon', 11, 340, 'It lives in snowy regions. It carves patterns in trees with its claws as a signal to others.', 215, 'Level up holding Razor Claw (night)'),
  (462, 'Magnezone', 4, 'electric', 'steel', 'Magnet Area Pokémon', 12, 1800, 'Exposure to a special magnetic field changed Magneton’s molecular structure, turning it into Magnezone.', 82, 'Level up at Mt Coronet'),
  (463, 'Lickilicky', 4, 'normal', null, 'Licking Pokémon', 17, 1400, 'Its saliva can decompose anything. It wraps its long tongue around things to coat them with its sticky saliva.', 108, 'Level up knowing Rollout'),
  (464, 'Rhyperior', 4, 'ground', 'rock', 'Drill Pokémon', 24, 2828, 'From holes in its palms, it fires out Geodude. Its carapace can withstand volcanic eruptions.', 112, 'Trade holding Protector'),
  (465, 'Tangrowth', 4, 'grass', null, 'Vine Pokémon', 20, 1286, 'When it remains still, it appears to be a large shrub. Unsuspecting prey that wander near get ensnared by its vines.', 114, 'Level up knowing Ancient Power'),
  (466, 'Electivire', 4, 'electric', null, 'Thunderbolt Pokémon', 18, 1386, 'As its electric charge amplifies, blue sparks begin to crackle between its horns.', 125, 'Trade holding Electirizer'),
  (467, 'Magmortar', 4, 'fire', null, 'Blast Pokémon', 16, 680, 'It blasts fireballs of over 3,600 degrees Fahrenheit out of its arms. Its breath also sears and sizzles.', 126, 'Trade holding Magmarizer'),
  (468, 'Togekiss', 4, 'fairy', 'flying', 'Jubilee Pokémon', 15, 380, 'As everyone knows, it visits peaceful regions, bringing them gifts of kindness and sweet blessings.', 176, 'Shiny Stone'),
  (469, 'Yanmega', 4, 'bug', 'flying', 'Ogre Darner Pokémon', 19, 515, 'This six-legged Pokémon is easily capable of transporting an adult in flight. The wings on its tail help it stay balanced.', 193, 'Level up knowing Ancient Power'),
  (470, 'Leafeon', 4, 'grass', null, 'Verdant Pokémon', 10, 255, 'When you see Leafeon asleep in a patch of sunshine, you’ll know it is using photosynthesis to produce clean air.', 133, 'Level up at Eterna Forest'),
  (471, 'Glaceon', 4, 'ice', null, 'Fresh Snow Pokémon', 8, 259, 'It causes small ice crystals to form by lowering the temperature of the surrounding atmosphere.', 133, 'Level up at Sinnoh Route 217'),
  (472, 'Gliscor', 4, 'ground', 'flying', 'Fang Scorpion Pokémon', 20, 425, 'Its flight is soundless. It uses its lengthy tail to carry off its prey... Then its elongated fangs do the rest.', 207, 'Level up holding Razor Fang (night)'),
  (473, 'Mamoswine', 4, 'ice', 'ground', 'Twin Tusk Pokémon', 25, 2910, 'A frozen Mamoswine was dug from ice dating back 10,000 years. This Pokémon has been around a long, long, long time.', 221, 'Level up knowing Ancient Power'),
  (474, 'Porygon-Z', 4, 'normal', null, 'Virtual Pokémon', 9, 340, 'Its programming was modified to enable it to travel through alien dimensions. Seems there might have been an error...', 233, 'Trade holding Dubious Disc'),
  (475, 'Gallade', 4, 'psychic', 'fighting', 'Blade Pokémon', 16, 520, 'Because it can sense what its foe is thinking, its attacks burst out first, fast, and fierce.', 281, 'Dawn Stone (male)'),
  (476, 'Probopass', 4, 'rock', 'steel', 'Compass Pokémon', 14, 3400, 'It controls three units called Mini-Noses using magnetic force. With them, it can attack the foe from three directions.', 299, 'Level up at Mt Coronet'),
  (477, 'Dusknoir', 4, 'ghost', null, 'Gripper Pokémon', 22, 1066, 'This feared Pokémon is said to travel to worlds unknown. Some even believe that it takes lost spirits along with it.', 356, 'Trade holding Reaper Cloth'),
  (478, 'Froslass', 4, 'ice', 'ghost', 'Snow Land Pokémon', 13, 266, 'Legends in snowy regions say that a woman who was lost on an icy mountain was reborn as Froslass.', 361, 'Dawn Stone (female)'),
  (479, 'Rotom', 4, 'electric', 'ghost', 'Plasma Pokémon', 3, 3, 'Research continues on this Pokémon, which could be the power source of a unique motor.', null, null),
  (480, 'Uxie', 4, 'psychic', null, 'Knowledge Pokémon', 3, 3, 'According to some sources, this Pokémon provided people with the intelligence necessary to solve various problems.', null, null),
  (481, 'Mesprit', 4, 'psychic', null, 'Emotion Pokémon', 3, 3, 'This Pokémon is said to have endowed the human heart with emotions, such as sorrow and joy.', null, null),
  (482, 'Azelf', 4, 'psychic', null, 'Willpower Pokémon', 3, 3, 'This Pokémon is said to have endowed humans with the determination needed to face any of life’s difficulties.', null, null),
  (483, 'Dialga', 4, 'steel', 'dragon', 'Temporal Pokémon', 54, 6830, 'This Pokémon completely controls the flow of time. It uses its power to travel at will through the past and future.', null, null),
  (484, 'Palkia', 4, 'water', 'dragon', 'Spatial Pokémon', 42, 3360, 'Its total control over the boundaries of space enable it to transport itself to faraway places or even other dimensions.', null, null),
  (485, 'Heatran', 4, 'fire', 'steel', 'Lava Dome Pokémon', 17, 4300, 'Boiling blood, like magma, circulates through its body. It makes its dwelling place in volcanic caves.', null, null),
  (486, 'Regigigas', 4, 'normal', null, 'Colossal Pokémon', 37, 4200, 'It is believed to have shaped Regirock, Regice, and Registeel out of clay, ice, and magma.', null, null),
  (487, 'Giratina', 4, 'ghost', 'dragon', 'Renegade Pokémon', 45, 7500, 'This Pokémon is said to live in a world on the reverse side of ours, where common knowledge is distorted and strange.', null, null),
  (488, 'Cresselia', 4, 'psychic', null, 'Lunar Pokémon', 15, 856, 'Those who sleep holding Cresselia’s feather are assured of joyful dreams. It is said to represent the crescent moon.', null, null),
  (489, 'Phione', 4, 'water', null, 'Sea Drifter Pokémon', 4, 31, 'When the water warms, they inflate the flotation sac on their heads and drift languidly on the sea in packs.', null, null),
  (490, 'Manaphy', 4, 'water', null, 'Seafaring Pokémon', 3, 14, 'It starts its life with a wondrous power that permits it to bond with any kind of Pokémon.', null, null),
  (491, 'Darkrai', 4, 'dark', null, 'Pitch-Black Pokémon', 15, 505, 'It chases people and Pokémon from its territory by causing them to experience deep, nightmarish slumbers.', null, null),
  (492, 'Shaymin', 4, 'grass', null, 'Gratitude Pokémon', 2, 21, 'The blooming of Gracidea flowers confers the power of flight upon it. Feelings of gratitude are the message it delivers.', null, null),
  (493, 'Arceus', 4, 'normal', null, 'Alpha Pokémon', 32, 3200, 'According to the legends of Sinnoh, this Pokémon emerged from an egg and shaped all there is in this world.', null, null),
  (494, 'Victini', 5, 'psychic', 'fire', 'Victory Pokémon', 4, 40, 'This Pokémon brings victory. It is said that Trainers with Victini always win, regardless of the type of encounter.', null, null),
  (495, 'Snivy', 5, 'grass', null, 'Grass Snake Pokémon', 6, 81, 'It is very intelligent and calm. Being exposed to lots of sunlight makes its movements swifter.', null, null),
  (496, 'Servine', 5, 'grass', null, 'Grass Snake Pokémon', 8, 160, 'It moves along the ground as if sliding. Its swift movements befuddle its foes, and it then attacks with a vine whip.', 495, 'Level 17'),
  (497, 'Serperior', 5, 'grass', null, 'Regal Pokémon', 33, 630, 'It can stop its opponents’ movements with just a glare. It takes in solar energy and boosts it internally.', 496, 'Level 36'),
  (498, 'Tepig', 5, 'fire', null, 'Fire Pig Pokémon', 5, 99, 'It can deftly dodge its foe’s attacks while shooting fireballs from its nose. It roasts berries before it eats them.', null, null),
  (499, 'Pignite', 5, 'fire', 'fighting', 'Fire Pig Pokémon', 10, 555, 'When its internal fire flares up, its movements grow sharper and faster. When in trouble, it emits smoke.', 498, 'Level 17'),
  (500, 'Emboar', 5, 'fire', 'fighting', 'Mega Fire Pig Pokémon', 16, 1500, 'It can throw a fire punch by setting its fists on fire with its fiery chin. It cares deeply about its friends.', 499, 'Level 36'),
  (501, 'Oshawott', 5, 'water', null, 'Sea Otter Pokémon', 5, 59, 'It fights using the scalchop on its stomach. In response to an attack, it retaliates immediately by slashing.', null, null),
  (502, 'Dewott', 5, 'water', null, 'Discipline Pokémon', 8, 245, 'Strict training is how it learns its flowing double-scalchop technique.', 501, 'Level 17'),
  (503, 'Samurott', 5, 'water', null, 'Formidable Pokémon', 15, 946, 'One swing of the sword incorporated in its armor can fell an opponent. A simple glare from one of them quiets everybody.', 502, 'Level 36'),
  (504, 'Patrat', 5, 'normal', null, 'Scout Pokémon', 5, 116, 'Using food stored in cheek pouches, they can keep watch for days. They use their tails to communicate with others.', null, null),
  (505, 'Watchog', 5, 'normal', null, 'Lookout Pokémon', 11, 270, 'When they see an enemy, their tails stand high, and they spit the seeds of berries stored in their cheek pouches.', 504, 'Level 20'),
  (506, 'Lillipup', 5, 'normal', null, 'Puppy Pokémon', 4, 41, 'It faces strong opponents with great courage. But, when at a disadvantage in a fight, this intelligent Pokémon flees.', null, null),
  (507, 'Herdier', 5, 'normal', null, 'Loyal Dog Pokémon', 9, 147, 'It has black, cape-like fur that is very hard and decreases the amount of damage it receives.', 506, 'Level 16'),
  (508, 'Stoutland', 5, 'normal', null, 'Big-Hearted Pokémon', 12, 610, 'It rescues people stranded by blizzards in the mountains. Its shaggy fur shields it from the cold.', 507, 'Level 32'),
  (509, 'Purrloin', 5, 'dark', null, 'Devious Pokémon', 4, 101, 'They steal from people for fun, but their victims can’t help but forgive them. Their deceptively cute act is perfect.', null, null),
  (510, 'Liepard', 5, 'dark', null, 'Cruel Pokémon', 11, 375, 'These Pokémon vanish and appear unexpectedly. Many Trainers are drawn to their beautiful form and fur.', 509, 'Level 20'),
  (511, 'Pansage', 5, 'grass', null, 'Grass Monkey Pokémon', 6, 105, 'This Pokémon dwells deep in the forest. Eating a leaf from its head whisks weariness away as if by magic.', null, null),
  (512, 'Simisage', 5, 'grass', null, 'Thorn Monkey Pokémon', 11, 305, 'Ill tempered, it fights by swinging its barbed tail around wildly. The leaf growing on its head is very bitter.', 511, 'Leaf Stone'),
  (513, 'Pansear', 5, 'fire', null, 'High Temp Pokémon', 6, 110, 'When it is angered, the temperature of its head tuft reaches 600° F. It uses its tuft to roast berries.', null, null),
  (514, 'Simisear', 5, 'fire', null, 'Ember Pokémon', 10, 280, 'It loves sweets because they become energy for the fire burning inside its body.', 513, 'Fire Stone'),
  (515, 'Panpour', 5, 'water', null, 'Spray Pokémon', 6, 135, 'The water stored inside the tuft on its head is full of nutrients. Plants that receive its water grow large.', null, null),
  (516, 'Simipour', 5, 'water', null, 'Geyser Pokémon', 10, 290, 'The tuft on its head holds water. When the level runs low, it replenishes the tuft by siphoning up water with its tail.', 515, 'Water Stone'),
  (517, 'Munna', 5, 'psychic', null, 'Dream Eater Pokémon', 6, 233, 'Munna always float in the air. People whose dreams are eaten by them forget what the dreams had been about.', null, null),
  (518, 'Musharna', 5, 'psychic', null, 'Drowsing Pokémon', 11, 605, 'The mist emanating from their foreheads is packed with the dreams of people and Pokémon.', 517, 'Moon Stone'),
  (519, 'Pidove', 5, 'normal', 'flying', 'Tiny Pigeon Pokémon', 3, 21, 'Each follows its Trainer’s orders as best it can, but they sometimes fail to understand complicated commands.', null, null),
  (520, 'Tranquill', 5, 'normal', 'flying', 'Wild Pigeon Pokémon', 6, 150, 'It can return to its Trainer’s location regardless of the distance separating them.', 519, 'Level 21'),
  (521, 'Unfezant', 5, 'normal', 'flying', 'Proud Pokémon', 12, 290, 'Males swing their head plumage to threaten opponents. The females’ flying abilities surpass those of the males.', 520, 'Level 32'),
  (522, 'Blitzle', 5, 'electric', null, 'Electrified Pokémon', 8, 298, 'Its mane shines when it discharges electricity. They use their flashing manes to communicate with one another.', null, null),
  (523, 'Zebstrika', 5, 'electric', null, 'Thunderbolt Pokémon', 16, 795, 'They have lightning-like movements. When Zebstrika run at full speed, the sound of thunder reverberates.', 522, 'Level 27'),
  (524, 'Roggenrola', 5, 'rock', null, 'Mantle Pokémon', 4, 180, 'Its ear is hexagonal in shape. Compressed underground, its body is as hard as steel.', null, null),
  (525, 'Boldore', 5, 'rock', null, 'Ore Pokémon', 9, 1020, 'When it overflows with power, the orange crystal on its body glows. It looks for underground water in caves.', 524, 'Level 25'),
  (526, 'Gigalith', 5, 'rock', null, 'Compressed Pokémon', 17, 2600, 'Compressing the energy from its internal core lets it fire off an attack capable of blowing away a mountain.', 525, 'Trade'),
  (527, 'Woobat', 5, 'psychic', 'flying', 'Bat Pokémon', 4, 21, 'Its habitat is dark forests and caves. It emits ultrasonic waves from its nose to learn about its surroundings.', null, null),
  (528, 'Swoobat', 5, 'psychic', 'flying', 'Courting Pokémon', 9, 105, 'It emits sound waves of various frequencies from its nose, including some powerful enough to destroy rocks.', 527, 'Friendship'),
  (529, 'Drilbur', 5, 'ground', null, 'Mole Pokémon', 3, 85, 'It can dig through the ground at a speed of 30 mph. It could give a car running aboveground a good race.', null, null),
  (530, 'Excadrill', 5, 'ground', 'steel', 'Subterrene Pokémon', 7, 404, 'It can help in tunnel construction. Its drill has evolved into steel strong enough to bore through iron plates.', 529, 'Level 31'),
  (531, 'Audino', 5, 'normal', null, 'Hearing Pokémon', 11, 310, 'It touches others with the feelers on its ears, using the sound of their heartbeats to tell how they are feeling.', null, null),
  (532, 'Timburr', 5, 'fighting', null, 'Muscular Pokémon', 6, 125, 'It fights by swinging a piece of lumber around. It is close to evolving when it can handle the lumber without difficulty.', null, null),
  (533, 'Gurdurr', 5, 'fighting', null, 'Muscular Pokémon', 12, 400, 'This Pokémon is so muscular and strongly built that even a group of wrestlers could not make it budge an inch.', 532, 'Level 25'),
  (534, 'Conkeldurr', 5, 'fighting', null, 'Muscular Pokémon', 14, 870, 'It is thought that Conkeldurr taught humans how to make concrete more than 2,000 years ago.', 533, 'Trade'),
  (535, 'Tympole', 5, 'water', null, 'Tadpole Pokémon', 5, 45, 'They warn others of danger by vibrating their cheeks to create a high-pitched sound.', null, null),
  (536, 'Palpitoad', 5, 'water', 'ground', 'Vibration Pokémon', 8, 170, 'When they vibrate the bumps on their heads, they can make waves in water or earthquake-like vibrations on land.', 535, 'Level 25'),
  (537, 'Seismitoad', 5, 'water', 'ground', 'Vibration Pokémon', 15, 620, 'They shoot paralyzing liquid from their head bumps. They use vibration to hurt their opponents.', 536, 'Level 36'),
  (538, 'Throh', 5, 'fighting', null, 'Judo Pokémon', 13, 555, 'When it tightens its belt, it becomes stronger. Wild Throh use vines to weave their own belts.', null, null),
  (539, 'Sawk', 5, 'fighting', null, 'Karate Pokémon', 14, 510, 'The sound of Sawk punching boulders and trees can be heard all the way from the mountains where they train.', null, null),
  (540, 'Sewaddle', 5, 'bug', 'grass', 'Sewing Pokémon', 3, 25, 'Leavanny dress it in clothes they made for it when it hatched. It hides its head in its hood while it is sleeping.', null, null),
  (541, 'Swadloon', 5, 'bug', 'grass', 'Leaf-Wrapped Pokémon', 5, 73, 'Forests where Swadloon live have superb foliage because the nutrients they make from fallen leaves nourish the plant life.', 540, 'Level 20'),
  (542, 'Leavanny', 5, 'bug', 'grass', 'Nurturing Pokémon', 12, 205, 'Upon finding a small Pokémon, it weaves clothing for it from leaves, using the cutters on its arms and sticky silk.', 541, 'Friendship'),
  (543, 'Venipede', 5, 'bug', 'poison', 'Centipede Pokémon', 4, 53, 'Its bite injects a potent poison, enough to paralyze large bird Pokémon that try to prey on it.', null, null),
  (544, 'Whirlipede', 5, 'bug', 'poison', 'Curlipede Pokémon', 12, 585, 'Protected by a hard shell, it spins its body like a wheel and crashes furiously into its enemies.', 543, 'Level 22'),
  (545, 'Scolipede', 5, 'bug', 'poison', 'Megapede Pokémon', 25, 2005, 'With quick movements, it chases down its foes, attacking relentlessly with its horns until it prevails.', 544, 'Level 30'),
  (546, 'Cottonee', 5, 'grass', 'fairy', 'Cotton Puff Pokémon', 3, 6, 'When attacked, it escapes by shooting cotton from its body. The cotton serves as a decoy to distract the attacker.', null, null),
  (547, 'Whimsicott', 5, 'grass', 'fairy', 'Windveiled Pokémon', 7, 66, 'Like the wind, it can slip through any gap, no matter how small. It leaves balls of white fluff behind.', 546, 'Sun Stone'),
  (548, 'Petilil', 5, 'grass', null, 'Bulb Pokémon', 5, 66, 'The leaves on its head are very bitter. Eating one of these leaves is known to refresh a tired body.', null, null),
  (549, 'Lilligant', 5, 'grass', null, 'Flowering Pokémon', 11, 163, 'Even veteran Trainers face a challenge in getting its beautiful flower to bloom. This Pokémon is popular with celebrities.', 548, 'Sun Stone'),
  (550, 'Basculin', 5, 'water', null, 'Hostile Pokémon', 10, 180, 'Red and blue Basculin get along so poorly, they’ll start fighting instantly. These Pokémon are very hostile.', null, null),
  (551, 'Sandile', 5, 'ground', 'dark', 'Desert Croc Pokémon', 7, 152, 'They live buried in the sands of the desert. The sun-warmed sands prevent their body temperature from dropping.', null, null),
  (552, 'Krokorok', 5, 'ground', 'dark', 'Desert Croc Pokémon', 10, 334, 'They live in groups of a few individuals. Protective membranes shield their eyes from sandstorms.', 551, 'Level 29'),
  (553, 'Krookodile', 5, 'ground', 'dark', 'Intimidation Pokémon', 15, 963, 'They never allow prey to escape. Their jaws are so powerful, they can crush the body of an automobile.', 552, 'Level 40'),
  (554, 'Darumaka', 5, 'fire', null, 'Zen Charm Pokémon', 6, 375, 'When its internal fire is burning, it cannot calm down and it runs around. When the fire diminishes, it falls asleep.', null, null),
  (555, 'Darmanitan', 5, 'fire', null, 'Blazing Pokémon', 13, 929, 'Its internal fire burns at 2,500° F, making enough power that it can destroy a dump truck with one punch.', 554, 'Level 35'),
  (556, 'Maractus', 5, 'grass', null, 'Cactus Pokémon', 10, 280, 'It uses an up-tempo song and dance to drive away the bird Pokémon that prey on its flower seeds.', null, null),
  (557, 'Dwebble', 5, 'bug', 'rock', 'Rock Inn Pokémon', 3, 145, 'This Pokémon can easily melt holes in hard rocks with a liquid secreted from its mouth.', null, null),
  (558, 'Crustle', 5, 'bug', 'rock', 'Stone Home Pokémon', 14, 2000, 'Competing for territory, Crustle fight viciously. The one whose boulder is broken is the loser of the battle.', 557, 'Level 34'),
  (559, 'Scraggy', 5, 'dark', 'fighting', 'Shedding Pokémon', 6, 118, 'Its skin has a rubbery elasticity, so it can reduce damage by defensively pulling its skin up to its neck.', null, null),
  (560, 'Scrafty', 5, 'dark', 'fighting', 'Hoodlum Pokémon', 11, 300, 'Groups of them beat up anything that enters their territory. Each can spit acidic liquid from its mouth.', 559, 'Level 39'),
  (561, 'Sigilyph', 5, 'psychic', 'flying', 'Avianoid Pokémon', 14, 140, 'They never vary the route they fly, because their memories of guarding an ancient city remain steadfast.', null, null),
  (562, 'Yamask', 5, 'ghost', null, 'Spirit Pokémon', 5, 15, 'Each of them carries a mask that used to be its face when it was human. Sometimes they look at it and cry.', null, null),
  (563, 'Cofagrigus', 5, 'ghost', null, 'Coffin Pokémon', 17, 765, 'It has been said that they swallow those who get too close and turn them into mummies. They like to eat gold nuggets.', 562, 'Level 34'),
  (564, 'Tirtouga', 5, 'water', 'rock', 'Prototurtle Pokémon', 7, 165, 'Restored from a fossil, this Pokémon can dive to depths beyond half a mile.', null, null),
  (565, 'Carracosta', 5, 'water', 'rock', 'Prototurtle Pokémon', 12, 810, 'They can live both in the ocean and on land. A slap from one of them is enough to open a hole in the bottom of a tanker.', 564, 'Level 37'),
  (566, 'Archen', 5, 'rock', 'flying', 'First Bird Pokémon', 5, 95, 'Said to be an ancestor of bird Pokémon, they were unable to fly and moved about by hopping from one branch to another.', null, null),
  (567, 'Archeops', 5, 'rock', 'flying', 'First Bird Pokémon', 14, 320, 'They are intelligent and will cooperate to catch prey. From the ground, they use a running start to take flight.', 566, 'Level 37'),
  (568, 'Trubbish', 5, 'poison', null, 'Trash Bag Pokémon', 6, 310, 'Inhaling the gas they belch will make you sleep for a week. They prefer unsanitary places.', null, null),
  (569, 'Garbodor', 5, 'poison', null, 'Trash Heap Pokémon', 19, 1073, 'It clenches opponents with its left arm and finishes them off with foul-smelling poison gas belched from its mouth.', 568, 'Level 36'),
  (570, 'Zorua', 5, 'dark', null, 'Tricky Fox Pokémon', 7, 125, 'It changes into the forms of others to surprise them. Apparently, it often transforms into a silent child.', null, null),
  (571, 'Zoroark', 5, 'dark', null, 'Illusion Fox Pokémon', 16, 811, 'Bonds between these Pokémon are very strong. It protects the safety of its pack by tricking its opponents.', 570, 'Level 30'),
  (572, 'Minccino', 5, 'normal', null, 'Chinchilla Pokémon', 4, 58, 'They greet one another by rubbing each other with their tails, which are always kept well groomed and clean.', null, null),
  (573, 'Cinccino', 5, 'normal', null, 'Scarf Pokémon', 5, 75, 'Their white fur is coated in a special oil that makes it easy for them to deflect attacks.', 572, 'Shiny Stone'),
  (574, 'Gothita', 5, 'psychic', null, 'Fixation Pokémon', 4, 58, 'Their ribbonlike feelers increase their psychic power. They are always staring at something.', null, null),
  (575, 'Gothorita', 5, 'psychic', null, 'Manipulate Pokémon', 7, 180, 'They use hypnosis to control people and Pokémon. Tales of Gothorita leading people astray are told in every corner.', 574, 'Level 32'),
  (576, 'Gothitelle', 5, 'psychic', null, 'Astral Body Pokémon', 15, 440, 'Starry skies thousands of light-years away are visible in the space distorted by their intense psychic power.', 575, 'Level 41'),
  (577, 'Solosis', 5, 'psychic', null, 'Cell Pokémon', 3, 10, 'They drive away attackers by unleashing psychic power. They can use telepathy to talk with others.', null, null),
  (578, 'Duosion', 5, 'psychic', null, 'Mitosis Pokémon', 6, 80, 'Since they have two divided brains, at times they suddenly try to take two different actions at once.', 577, 'Level 32'),
  (579, 'Reuniclus', 5, 'psychic', null, 'Multiplying Pokémon', 10, 201, 'When Reuniclus shake hands, a network forms between their brains, increasing their psychic power.', 578, 'Level 41'),
  (580, 'Ducklett', 5, 'water', 'flying', 'Water Bird Pokémon', 5, 55, 'These bird Pokémon are excellent divers. They swim around in the water eating their favorite food--peat moss.', null, null),
  (581, 'Swanna', 5, 'water', 'flying', 'White Bird Pokémon', 13, 242, 'Swanna start to dance at dusk. The one dancing in the middle is the leader of the flock.', 580, 'Level 35'),
  (582, 'Vanillite', 5, 'ice', null, 'Fresh Snow Pokémon', 4, 57, 'The temperature of their breath is -58° F. They create snow crystals and make snow fall in the areas around them.', null, null),
  (583, 'Vanillish', 5, 'ice', null, 'Icy Snow Pokémon', 11, 410, 'Snowy mountains are this Pokémon’s habitat. During an ancient ice age, they moved to southern areas.', 582, 'Level 35'),
  (584, 'Vanilluxe', 5, 'ice', null, 'Snowstorm Pokémon', 13, 575, 'Swallowing large amounts of water, they make snow clouds inside their bodies and attack their foes with violent blizzards.', 583, 'Level 47'),
  (585, 'Deerling', 5, 'normal', 'grass', 'Season Pokémon', 6, 195, 'The color and scent of their fur changes to match the mountain grass. When they sense hostility, they hide in the grass.', null, null),
  (586, 'Sawsbuck', 5, 'normal', 'grass', 'Season Pokémon', 19, 925, 'They migrate according to the seasons. People can tell the season by looking at Sawsbuck’s horns.', 585, 'Level 34'),
  (587, 'Emolga', 5, 'electric', 'flying', 'Sky Squirrel Pokémon', 4, 50, 'The energy made in its cheeks’ electric pouches is stored inside its membrane and released while it is gliding.', null, null),
  (588, 'Karrablast', 5, 'bug', null, 'Clamping Pokémon', 5, 59, 'These mysterious Pokémon evolve when they receive electrical stimulation while they are in the same place as Shelmet.', null, null),
  (589, 'Escavalier', 5, 'bug', 'steel', 'Cavalry Pokémon', 10, 330, 'They fly around at high speed, striking with their pointed spears. Even when in trouble, they face opponents bravely.', 588, 'Trade for Shelmet'),
  (590, 'Foongus', 5, 'grass', 'poison', 'Mushroom Pokémon', 2, 10, 'It lures people in with its Poké Ball pattern, then releases poison spores. Why it resembles a Poké Ball is unknown.', null, null),
  (591, 'Amoonguss', 5, 'grass', 'poison', 'Mushroom Pokémon', 6, 105, 'It lures prey close by dancing and waving its arm caps, which resemble Poké Balls, in a swaying motion.', 590, 'Level 39'),
  (592, 'Frillish', 5, 'water', 'ghost', 'Floating Pokémon', 12, 330, 'With its thin, veil-like arms wrapped around the body of its opponent, it sinks to the ocean floor.', null, null),
  (593, 'Jellicent', 5, 'water', 'ghost', 'Floating Pokémon', 22, 1350, 'The fate of the ships and crew that wander into Jellicent’s habitat: all sunken, all lost, all vanished.', 592, 'Level 40'),
  (594, 'Alomomola', 5, 'water', null, 'Caring Pokémon', 12, 316, 'The special membrane enveloping Alomomola has the ability to heal wounds.', null, null),
  (595, 'Joltik', 5, 'bug', 'electric', 'Attaching Pokémon', 1, 6, 'Joltik that live in cities have learned a technique for sucking electricity from the outlets in houses.', null, null),
  (596, 'Galvantula', 5, 'bug', 'electric', 'EleSpider Pokémon', 8, 143, 'When attacked, they create an electric barrier by spitting out many electrically charged threads.', 595, 'Level 36'),
  (597, 'Ferroseed', 5, 'grass', 'steel', 'Thorn Seed Pokémon', 6, 188, 'When threatened, it attacks by shooting a barrage of spikes, which gives it a chance to escape by rolling away.', null, null),
  (598, 'Ferrothorn', 5, 'grass', 'steel', 'Thorn Pod Pokémon', 10, 1100, 'It fights by swinging around its three spiky feelers. A hit from these steel spikes can reduce a boulder to rubble.', 597, 'Level 40'),
  (599, 'Klink', 5, 'steel', null, 'Gear Pokémon', 3, 210, 'The two minigears that mesh together are predetermined. Each will rebound from other minigears without meshing.', null, null),
  (600, 'Klang', 5, 'steel', null, 'Gear Pokémon', 6, 510, 'By changing the direction in which it rotates, it communicates its feelings to others. When angry, it rotates faster.', 599, 'Level 38'),
  (601, 'Klinklang', 5, 'steel', null, 'Gear Pokémon', 6, 810, 'Its red core functions as an energy tank. It fires the charged energy through its spikes into an area.', 600, 'Level 49'),
  (602, 'Tynamo', 5, 'electric', null, 'EleFish Pokémon', 2, 3, 'While one alone doesn’t have much power, a chain of many Tynamo can be as powerful as lightning.', null, null),
  (603, 'Eelektrik', 5, 'electric', null, 'EleFish Pokémon', 12, 220, 'They coil around foes and shock them with electricity-generating organs that seem simply to be circular patterns.', 602, 'Level 39'),
  (604, 'Eelektross', 5, 'electric', null, 'EleFish Pokémon', 21, 805, 'They crawl out of the ocean using their arms. They will attack prey on shore and immediately drag it into the ocean.', 603, 'Thunder Stone'),
  (605, 'Elgyem', 5, 'psychic', null, 'Cerebral Pokémon', 5, 90, 'It uses its strong psychic power to squeeze its opponent’s brain, causing unendurable headaches.', null, null),
  (606, 'Beheeyem', 5, 'psychic', null, 'Cerebral Pokémon', 10, 345, 'It can manipulate an opponent’s memory. Apparently, it communicates by flashing its three different-colored fingers.', 605, 'Level 42'),
  (607, 'Litwick', 5, 'ghost', 'fire', 'Candle Pokémon', 3, 31, 'Litwick shines a light that absorbs the life energy of people and Pokémon, which becomes the fuel that it burns.', null, null),
  (608, 'Lampent', 5, 'ghost', 'fire', 'Lamp Pokémon', 6, 130, 'This ominous Pokémon is feared. Through cities it wanders, searching for the spirits of the fallen.', 607, 'Level 41'),
  (609, 'Chandelure', 5, 'ghost', 'fire', 'Luring Pokémon', 10, 343, 'It absorbs a spirit, which it then burns. By waving the flames on its arms, it puts its foes into a hypnotic trance.', 608, 'Dusk Stone'),
  (610, 'Axew', 5, 'dragon', null, 'Tusk Pokémon', 6, 180, 'They use their tusks to crush the berries they eat. Repeated regrowth makes their tusks strong and sharp.', null, null),
  (611, 'Fraxure', 5, 'dragon', null, 'Axe Jaw Pokémon', 10, 360, 'Since a broken tusk will not grow back, they diligently sharpen their tusks on river rocks after they’ve been fighting.', 610, 'Level 38'),
  (612, 'Haxorus', 5, 'dragon', null, 'Axe Jaw Pokémon', 18, 1055, 'They are kind but can be relentless when defending territory. They challenge foes with tusks that can cut steel.', 611, 'Level 48'),
  (613, 'Cubchoo', 5, 'ice', null, 'Chill Pokémon', 5, 85, 'When it is not feeling well, its mucus gets watery and the power of its Ice-type moves decreases.', null, null),
  (614, 'Beartic', 5, 'ice', null, 'Freezing Pokémon', 26, 2600, 'It can make its breath freeze at will. Very able in the water, it swims around in northern seas and catches prey.', 613, 'Level 37'),
  (615, 'Cryogonal', 5, 'ice', null, 'Crystallizing Pokémon', 11, 1480, 'When its body temperature goes up, it turns into steam and vanishes. When its temperature lowers, it returns to ice.', null, null),
  (616, 'Shelmet', 5, 'bug', null, 'Snail Pokémon', 4, 77, 'When attacked, it defends itself by closing the lid of its shell. It can spit a sticky, poisonous liquid.', null, null),
  (617, 'Accelgor', 5, 'bug', null, 'Shell Out Pokémon', 8, 253, 'When its body dries out, it weakens. So, to prevent dehydration, it wraps itself in many layers of thin membrane.', 616, 'Trade for Karrablast'),
  (618, 'Stunfisk', 5, 'ground', 'electric', 'Trap Pokémon', 7, 110, 'Its skin is very hard, so it is unhurt even if stepped on by sumo wrestlers. It smiles when transmitting electricity.', null, null),
  (619, 'Mienfoo', 5, 'fighting', null, 'Martial Arts Pokémon', 9, 200, 'In fights, they dominate with onslaughts of flowing, continuous attacks. With their sharp claws, they cut enemies.', null, null),
  (620, 'Mienshao', 5, 'fighting', null, 'Martial Arts Pokémon', 14, 355, 'It wields the fur on its arms like a whip. Its arm attacks come with such rapidity that they cannot even be seen.', 619, 'Level 50'),
  (621, 'Druddigon', 5, 'dragon', null, 'Cave Pokémon', 16, 1390, 'It warms its body by absorbing sunlight with its wings. When its body temperature falls, it can no longer move.', null, null),
  (622, 'Golett', 5, 'ground', 'ghost', 'Automaton Pokémon', 10, 920, 'The energy that burns inside it enables it to move, but no one has yet been able to identify this energy.', null, null),
  (623, 'Golurk', 5, 'ground', 'ghost', 'Automaton Pokémon', 28, 3300, 'It flies across the sky at Mach speeds. Removing the seal on its chest makes its internal energy go out of control.', 622, 'Level 43'),
  (624, 'Pawniard', 5, 'dark', 'steel', 'Sharp Blade Pokémon', 5, 102, 'Blades comprise this Pokémon’s entire body. If battling dulls the blades, it sharpens them on stones by the river.', null, null),
  (625, 'Bisharp', 5, 'dark', 'steel', 'Sword Blade Pokémon', 16, 700, 'It leads a group of Pawniard. It battles to become the boss, but will be driven from the group if it loses.', 624, 'Level 52'),
  (626, 'Bouffalant', 5, 'normal', null, 'Bash Buffalo Pokémon', 16, 946, 'Their fluffy fur absorbs damage, even if they strike foes with a fierce headbutt.', null, null),
  (627, 'Rufflet', 5, 'normal', 'flying', 'Eaglet Pokémon', 5, 105, 'They crush berries with their talons. They bravely stand up to any opponent, no matter how strong it is.', null, null),
  (628, 'Braviary', 5, 'normal', 'flying', 'Valiant Pokémon', 15, 410, 'They fight for their friends without any thought about danger to themselves. One can carry a car while flying.', 627, 'Level 54'),
  (629, 'Vullaby', 5, 'dark', 'flying', 'Diapered Pokémon', 5, 90, 'Its wings are too tiny to allow it to fly. As the time approaches for it to evolve, it discards the bones it was wearing.', null, null),
  (630, 'Mandibuzz', 5, 'dark', 'flying', 'Bone Vulture Pokémon', 12, 395, 'It makes a nest out of bones it finds. It grabs weakened prey in its talons and hauls it to its nest of bones.', 629, 'Level 54'),
  (631, 'Heatmor', 5, 'fire', null, 'Anteater Pokémon', 14, 580, 'It breathes through a hole in its tail while it burns with an internal fire. Durant is its prey.', null, null),
  (632, 'Durant', 5, 'bug', 'steel', 'Iron Ant Pokémon', 3, 330, 'They attack in groups, covering themselves in steel armor to protect themselves from Heatmor.', null, null),
  (633, 'Deino', 5, 'dark', 'dragon', 'Irate Pokémon', 8, 173, 'It tends to bite everything, and it is not a picky eater. Approaching it carelessly is dangerous.', null, null),
  (634, 'Zweilous', 5, 'dark', 'dragon', 'Hostile Pokémon', 14, 500, 'After it has eaten up all the food in its territory, it moves to another area. Its two heads do not get along.', 633, 'Level 50'),
  (635, 'Hydreigon', 5, 'dark', 'dragon', 'Brutal Pokémon', 18, 1600, 'This brutal Pokémon travels the skies on its six wings. Anything that moves seems like a foe to it, triggering its attack.', 634, 'Level 64'),
  (636, 'Larvesta', 5, 'bug', 'fire', 'Torch Pokémon', 11, 288, 'This Pokémon was believed to have been born from the sun. When it evolves, its entire body is engulfed in flames.', null, null),
  (637, 'Volcarona', 5, 'bug', 'fire', 'Sun Pokémon', 16, 460, 'When volcanic ash darkened the atmosphere, it is said that Volcarona’s fire provided a replacement for the sun.', 636, 'Level 59'),
  (638, 'Cobalion', 5, 'steel', 'fighting', 'Iron Will Pokémon', 21, 2500, 'This legendary Pokémon battled against humans to protect Pokémon. Its personality is calm and composed.', null, null),
  (639, 'Terrakion', 5, 'rock', 'fighting', 'Cavern Pokémon', 19, 2600, 'This Pokémon came to the defense of Pokémon that had lost their homes in a war among humans.', null, null),
  (640, 'Virizion', 5, 'grass', 'fighting', 'Grassland Pokémon', 20, 2000, 'This Pokémon fought humans in order to protect its friends. Legends about it continue to be passed down.', null, null),
  (641, 'Tornadus', 5, 'flying', null, 'Cyclone Pokémon', 15, 630, 'The lower half of its body is wrapped in a cloud of energy. It zooms through the sky at 200 mph.', null, null),
  (642, 'Thundurus', 5, 'electric', 'flying', 'Bolt Strike Pokémon', 15, 610, 'Countless charred remains mar the landscape of places through which Thundurus has passed.', null, null),
  (643, 'Reshiram', 5, 'dragon', 'fire', 'Vast White Pokémon', 32, 3300, 'This Pokémon appears in legends. It sends flames into the air from its tail, burning up everything around it.', null, null),
  (644, 'Zekrom', 5, 'dragon', 'electric', 'Deep Black Pokémon', 29, 3450, 'Concealing itself in lightning clouds, it flies throughout the Unova region. It creates electricity in its tail.', null, null),
  (645, 'Landorus', 5, 'ground', 'flying', 'Abundance Pokémon', 15, 680, 'Lands visited by Landorus grant such bountiful crops that it has been hailed as “The Guardian of the Fields.”', null, null),
  (646, 'Kyurem', 5, 'dragon', 'ice', 'Boundary Pokémon', 30, 3250, 'It generates a powerful, freezing energy inside itself, but its body became frozen when the energy leaked out.', null, null),
  (647, 'Keldeo', 5, 'water', 'fighting', 'Colt Pokémon', 14, 485, 'By blasting water from its hooves, it can glide across water. It excels at using leg moves while battling.', null, null),
  (648, 'Meloetta', 5, 'normal', 'psychic', 'Melody Pokémon', 6, 65, 'Its melodies are sung with a special vocalization method that can control the feelings of those who hear it.', null, null),
  (649, 'Genesect', 5, 'bug', 'steel', 'Paleozoic Pokémon', 15, 825, 'Over 300 million years ago, it was feared as the strongest of hunters. It has been modified by Team Plasma.', null, null),
  (650, 'Chespin', 6, 'grass', null, 'Spiny Nut Pokémon', 4, 90, 'The quills on its head are usually soft. When it flexes them, the points become so hard and sharp that they can pierce rock.', null, null),
  (651, 'Quilladin', 6, 'grass', null, 'Spiny Armor Pokémon', 7, 290, 'It relies on its sturdy shell to deflect predators’ attacks. It counterattacks with its sharp quills.', 650, 'Level 16'),
  (652, 'Chesnaught', 6, 'grass', 'fighting', 'Spiny Armor Pokémon', 16, 900, 'Its Tackle is forceful enough to flip a 50-ton tank. It shields its allies from danger with its own body.', 651, 'Level 36'),
  (653, 'Fennekin', 6, 'fire', null, 'Fox Pokémon', 4, 94, 'Eating a twig fills it with energy, and its roomy ears give vent to air hotter than 390 degrees Fahrenheit.', null, null),
  (654, 'Braixen', 6, 'fire', null, 'Fox Pokémon', 10, 145, 'It has a twig stuck in its tail. With friction from its tail fur, it sets the twig on fire and launches into battle.', 653, 'Level 16'),
  (655, 'Delphox', 6, 'fire', 'psychic', 'Fox Pokémon', 15, 390, 'It gazes into the flame at the tip of its branch to achieve a focused state, which allows it to see into the future.', 654, 'Level 36'),
  (656, 'Froakie', 6, 'water', null, 'Bubble Frog Pokémon', 3, 70, 'It secretes flexible bubbles from its chest and back. The bubbles reduce the damage it would otherwise take when attacked.', null, null),
  (657, 'Frogadier', 6, 'water', null, 'Bubble Frog Pokémon', 6, 109, 'It can throw bubble-covered pebbles with precise control, hitting empty cans up to a hundred feet away.', 656, 'Level 16'),
  (658, 'Greninja', 6, 'water', 'dark', 'Ninja Pokémon', 15, 400, 'It creates throwing stars out of compressed water. When it spins them and throws them at high speed, these stars can split metal in two.', 657, 'Level 36'),
  (659, 'Bunnelby', 6, 'normal', null, 'Digging Pokémon', 4, 50, 'They use their large ears to dig burrows. They will dig the whole night through.', null, null),
  (660, 'Diggersby', 6, 'normal', 'ground', 'Digging Pokémon', 10, 424, 'With their powerful ears, they can heft boulders of a ton or more with ease. They can be a big help at construction sites.', 659, 'Level 20'),
  (661, 'Fletchling', 6, 'normal', 'flying', 'Tiny Robin Pokémon', 3, 17, 'These friendly Pokémon send signals to one another with beautiful chirps and tail-feather movements.', null, null),
  (662, 'Fletchinder', 6, 'fire', 'flying', 'Ember Pokémon', 7, 160, 'From its beak, it expels embers that set the tall grass on fire. Then it pounces on the bewildered prey that pop out of the grass.', 661, 'Level 17'),
  (663, 'Talonflame', 6, 'fire', 'flying', 'Scorching Pokémon', 12, 245, 'In the fever of an exciting battle, it showers embers from the gaps between its feathers and takes to the air.', 662, 'Level 35'),
  (664, 'Scatterbug', 6, 'bug', null, 'Scatterdust Pokémon', 3, 25, 'When under attack from bird Pokémon, it spews a poisonous black powder that causes paralysis on contact.', null, null),
  (665, 'Spewpa', 6, 'bug', null, 'Scatterdust Pokémon', 3, 84, 'It lives hidden within thicket shadows. When predators attack, it quickly bristles the fur covering its body in an effort to threaten them.', 664, 'Level 9'),
  (666, 'Vivillon', 6, 'bug', 'flying', 'Scale Pokémon', 12, 170, 'Vivillon with many different patterns are found all over the world. These patterns are affected by the climate of their habitat.', 665, 'Level 12'),
  (667, 'Litleo', 6, 'fire', 'normal', 'Lion Cub Pokémon', 6, 135, 'The stronger the opponent it faces, the more heat surges from its mane and the more power flows through its body.', null, null),
  (668, 'Pyroar', 6, 'fire', 'normal', 'Royal Pokémon', 15, 815, 'The male with the largest mane of fire is the leader of the pride.', 667, 'Level 35'),
  (669, 'Flabébé', 6, 'fairy', null, 'Single Bloom Pokémon', 1, 1, 'It draws out and controls the hidden power of flowers. The flower Flabébé holds is most likely part of its body.', null, null),
  (670, 'Floette', 6, 'fairy', null, 'Single Bloom Pokémon', 2, 9, 'It flutters around fields of flowers and cares for flowers that are starting to wilt. It draws out the hidden power of flowers to battle.', 669, 'Level 19'),
  (671, 'Florges', 6, 'fairy', null, 'Garden Pokémon', 11, 100, 'It claims exquisite flower gardens as its territory, and it obtains power from basking in the energy emitted by flowering plants.', 670, 'Shiny Stone'),
  (672, 'Skiddo', 6, 'grass', null, 'Mount Pokémon', 9, 310, 'Thought to be one of the first Pokémon to live in harmony with humans, it has a placid disposition.', null, null),
  (673, 'Gogoat', 6, 'grass', null, 'Mount Pokémon', 17, 910, 'It can tell how its Trainer is feeling by subtle shifts in the grip on its horns. This empathic sense lets them run as if one being.', 672, 'Level 32'),
  (674, 'Pancham', 6, 'fighting', null, 'Playful Pokémon', 6, 80, 'It does its best to be taken seriously by its enemies, but its glare is not sufficiently intimidating. Chewing on a leaf is its trademark.', null, null),
  (675, 'Pangoro', 6, 'fighting', 'dark', 'Daunting Pokémon', 21, 1360, 'Although it possesses a violent temperament, it won’t put up with bullying. It uses the leaf in its mouth to sense the movements of its enemies.', 674, 'Level 32'),
  (676, 'Furfrou', 6, 'normal', null, 'Poodle Pokémon', 12, 280, 'Trimming its fluffy fur not only makes it more elegant but also increases the swiftness of its movements.', null, null),
  (677, 'Espurr', 6, 'psychic', null, 'Restraint Pokémon', 3, 35, 'The organ that emits its intense psychic power is sheltered by its ears to keep power from leaking out.', null, null),
  (678, 'Meowstic', 6, 'psychic', null, 'Constraint Pokémon', 6, 85, 'When in danger, it raises its ears and releases enough psychic power to grind a 10-ton truck into dust.', 677, 'Level 25 (male)'),
  (679, 'Honedge', 6, 'steel', 'ghost', 'Sword Pokémon', 8, 20, 'Apparently this Pokémon is born when a departed spirit inhabits a sword. It attaches itself to people and drinks their life force.', null, null),
  (680, 'Doublade', 6, 'steel', 'ghost', 'Sword Pokémon', 8, 45, 'When Honedge evolves, it divides into two swords, which cooperate via telepathy to coordinate attacks and slash their enemies to ribbons.', 679, 'Level 35'),
  (681, 'Aegislash', 6, 'steel', 'ghost', 'Royal Sword Pokémon', 17, 530, 'Generations of kings were attended by these Pokémon, which used their spectral power to manipulate and control people and Pokémon.', 680, 'Dusk Stone'),
  (682, 'Spritzee', 6, 'fairy', null, 'Perfume Pokémon', 2, 5, 'It emits a scent that enraptures those who smell it. This fragrance changes depending on what it has eaten.', null, null),
  (683, 'Aromatisse', 6, 'fairy', null, 'Fragrance Pokémon', 8, 155, 'It devises various scents, pleasant and unpleasant, and emits scents that its enemies dislike in order to gain an edge in battle.', 682, 'Trade holding Sachet'),
  (684, 'Swirlix', 6, 'fairy', null, 'Cotton Candy Pokémon', 4, 35, 'To entangle its opponents in battle, it extrudes white threads as sweet and sticky as cotton candy.', null, null),
  (685, 'Slurpuff', 6, 'fairy', null, 'Meringue Pokémon', 8, 50, 'It can distinguish the faintest of scents. It puts its sensitive sense of smell to use by helping pastry chefs in their work.', 684, 'Trade holding Whipped Dream'),
  (686, 'Inkay', 6, 'dark', 'psychic', 'Revolving Pokémon', 4, 35, 'Opponents who stare at the flashing of the light-emitting spots on its body become dazed and lose their will to fight.', null, null),
  (687, 'Malamar', 6, 'dark', 'psychic', 'Overturning Pokémon', 15, 470, 'It wields the most compelling hypnotic powers of any Pokémon, and it forces others to do whatever it wants.', 686, 'Level 30, upside down'),
  (688, 'Binacle', 6, 'rock', 'water', 'Two-Handed Pokémon', 5, 310, 'Two Binacle live together on one rock. When they fight, one of them will move to a different rock.', null, null),
  (689, 'Barbaracle', 6, 'rock', 'water', 'Collective Pokémon', 13, 960, 'When they evolve, two Binacle multiply into seven. They fight with the power of seven Binacle.', 688, 'Level 39'),
  (690, 'Skrelp', 6, 'poison', 'water', 'Mock Kelp Pokémon', 5, 73, 'Camouflaged as rotten kelp, they spray liquid poison on prey that approaches unawares and then finish it off.', null, null),
  (691, 'Dragalge', 6, 'poison', 'dragon', 'Mock Kelp Pokémon', 18, 815, 'Their poison is strong enough to eat through the hull of a tanker, and they spit it indiscriminately at anything that enters their territory.', 690, 'Level 48'),
  (692, 'Clauncher', 6, 'water', null, 'Water Gun Pokémon', 5, 83, 'They knock down flying prey by firing compressed water from their massive claws like shooting a pistol.', null, null),
  (693, 'Clawitzer', 6, 'water', null, 'Howitzer Pokémon', 13, 353, 'Their enormous claws launch cannonballs of water powerful enough to pierce tanker hulls.', 692, 'Level 37'),
  (694, 'Helioptile', 6, 'electric', 'normal', 'Generator Pokémon', 5, 60, 'They make their home in deserts. They can generate their energy from basking in the sun, so eating food is not a requirement.', null, null),
  (695, 'Heliolisk', 6, 'electric', 'normal', 'Generator Pokémon', 10, 210, 'They flare their frills and generate energy. A single Heliolisk can generate sufficient electricity to power a skyscraper.', 694, 'Sun Stone'),
  (696, 'Tyrunt', 6, 'rock', 'dragon', 'Royal Heir Pokémon', 8, 260, 'This Pokémon was restored from a fossil. If something happens that it doesn’t like, it throws a tantrum and runs wild.', null, null),
  (697, 'Tyrantrum', 6, 'rock', 'dragon', 'Despot Pokémon', 25, 2700, 'Thanks to its gargantuan jaws, which could shred thick metal plates as if they were paper, it was invincible in the ancient world it once inhabited.', 696, 'Level 39 (day)'),
  (698, 'Amaura', 6, 'rock', 'ice', 'Tundra Pokémon', 13, 252, 'This ancient Pokémon was restored from part of its body that had been frozen in ice for over 100 million years.', null, null),
  (699, 'Aurorus', 6, 'rock', 'ice', 'Tundra Pokémon', 27, 2250, 'The diamond-shaped crystals on its body expel air as cold as -240 degrees Fahrenheit, surrounding its enemies and encasing them in ice.', 698, 'Level 39 (night)'),
  (700, 'Sylveon', 6, 'fairy', null, 'Intertwining Pokémon', 10, 235, 'It sends a soothing aura from its ribbonlike feelers to calm fights.', 133, 'Affection'),
  (701, 'Hawlucha', 6, 'fighting', 'flying', 'Wrestling Pokémon', 8, 215, 'Although its body is small, its proficient fighting skills enable it to keep up with big bruisers like Machamp and Hariyama.', null, null),
  (702, 'Dedenne', 6, 'electric', 'fairy', 'Antenna Pokémon', 2, 22, 'Its whiskers serve as antennas. By sending and receiving electrical waves, it can communicate with others over vast distances.', null, null),
  (703, 'Carbink', 6, 'rock', 'fairy', 'Jewel Pokémon', 3, 57, 'Born from the temperatures and pressures deep underground, it fires beams from the stone in its head.', null, null),
  (704, 'Goomy', 6, 'dragon', null, 'Soft Tissue Pokémon', 3, 28, 'The weakest Dragon-type Pokémon, it lives in damp, shady places, so its body doesn’t dry out.', null, null),
  (705, 'Sliggoo', 6, 'dragon', null, 'Soft Tissue Pokémon', 8, 175, 'It drives away opponents by excreting a sticky liquid that can dissolve anything. Its eyes devolved, so it can’t see anything.', 704, 'Level 40'),
  (706, 'Goodra', 6, 'dragon', null, 'Dragon Pokémon', 20, 1505, 'This very friendly Dragon-type Pokémon will hug its beloved Trainer, leaving that Trainer covered in sticky slime.', 705, 'Level 50, in the rain'),
  (707, 'Klefki', 6, 'steel', 'fairy', 'Key Ring Pokémon', 2, 30, 'These key collectors threaten any attackers by fiercely jingling their keys at them.', null, null),
  (708, 'Phantump', 6, 'ghost', 'grass', 'Stump Pokémon', 4, 70, 'These Pokémon are created when spirits possess rotten tree stumps. They prefer to live in abandoned forests.', null, null),
  (709, 'Trevenant', 6, 'ghost', 'grass', 'Elder Tree Pokémon', 15, 710, 'It can control trees at will. It will trap people who harm the forest, so they can never leave.', 708, 'Trade'),
  (710, 'Pumpkaboo', 6, 'ghost', 'grass', 'Pumpkin Pokémon', 4, 50, 'The pumpkin body is inhabited by a spirit trapped in this world. As the sun sets, it becomes restless and active.', null, null),
  (711, 'Gourgeist', 6, 'ghost', 'grass', 'Pumpkin Pokémon', 9, 125, 'Singing in eerie voices, they wander town streets on the night of the new moon. Anyone who hears their song is cursed.', 710, 'Trade'),
  (712, 'Bergmite', 6, 'ice', null, 'Ice Chunk Pokémon', 10, 995, 'It blocks opponents’ attacks with the ice that shields its body. It uses cold air to repair any cracks with new ice.', null, null),
  (713, 'Avalugg', 6, 'ice', null, 'Iceberg Pokémon', 20, 5050, 'Its ice-covered body is as hard as steel. Its cumbersome frame crushes anything that stands in its way.', 712, 'Level 37'),
  (714, 'Noibat', 6, 'flying', 'dragon', 'Sound Wave Pokémon', 5, 80, 'They live in pitch-black caves. Their enormous ears can emit ultrasonic waves of 200,000 hertz.', null, null),
  (715, 'Noivern', 6, 'flying', 'dragon', 'Sound Wave Pokémon', 15, 850, 'They fly around on moonless nights and attack careless prey. Nothing can beat them in a battle in the dark.', 714, 'Level 48'),
  (716, 'Xerneas', 6, 'fairy', null, 'Life Pokémon', 30, 2150, 'Legends say it can share eternal life. It slept for a thousand years in the form of a tree before its revival.', null, null),
  (717, 'Yveltal', 6, 'dark', 'flying', 'Destruction Pokémon', 58, 2030, 'When this legendary Pokémon’s wings and tail feathers spread wide and glow red, it absorbs the life force of living creatures.', null, null),
  (718, 'Zygarde', 6, 'dragon', 'ground', 'Order Pokémon', 50, 3050, 'When the Kalos region’s ecosystem falls into disarray, it appears and reveals its secret power.', null, null),
  (719, 'Diancie', 6, 'rock', 'fairy', 'Jewel Pokémon', 7, 88, 'A sudden transformation of Carbink, its pink, glimmering body is said to be the loveliest sight in the whole world.', null, null),
  (720, 'Hoopa', 6, 'psychic', 'ghost', 'Mischief Pokémon', 5, 90, 'This troublemaker sends anything and everything to faraway places using its loop, which can warp space.', null, null),
  (721, 'Volcanion', 6, 'fire', 'water', 'Steam Pokémon', 17, 1950, 'It lets out billows of steam and disappears into the dense fog. It’s said to live in mountains where humans do not tread.', null, null),
  (722, 'Rowlet', 7, 'grass', 'flying', 'Grass Quill Pokémon', 3, 15, 'This wary Pokémon uses photosynthesis to store up energy during the day, while becoming active at night.', null, null),
  (723, 'Dartrix', 7, 'grass', 'flying', 'Blade Quill Pokémon', 7, 160, 'A bit of a dandy, it spends its free time preening its wings. Its preoccupation with any dirt on its plumage can leave it unable to battle.', 722, 'Level 17'),
  (724, 'Decidueye', 7, 'grass', 'ghost', 'Arrow Quill Pokémon', 16, 366, 'It fires arrow quills from its wings with such precision, they can pierce a pebble at distances over a hundred yards.', 723, 'Level 34'),
  (725, 'Litten', 7, 'fire', null, 'Fire Cat Pokémon', 4, 43, 'While grooming itself, it builds up fur inside its stomach. It sets the fur alight and spews fiery attacks, which change based on how it coughs.', null, null),
  (726, 'Torracat', 7, 'fire', null, 'Fire Cat Pokémon', 7, 250, 'At its throat, it bears a bell of fire. The bell rings brightly whenever this Pokémon spits fire.', 725, 'Level 17'),
  (727, 'Incineroar', 7, 'fire', 'dark', 'Heel Pokémon', 18, 830, 'This Pokémon has a violent, selfish disposition. If it’s not in the mood to listen, it will ignore its Trainer’s orders with complete nonchalance.', 726, 'Level 34'),
  (728, 'Popplio', 7, 'water', null, 'Sea Lion Pokémon', 4, 75, 'This Pokémon snorts body fluids from its nose, blowing balloons to smash into its foes. It’s famous for being a hard worker.', null, null),
  (729, 'Brionne', 7, 'water', null, 'Pop Star Pokémon', 6, 175, 'A skillful dancer, it creates a sequence of water balloons as it dances, and briskly bombards its enemies.', 728, 'Level 17'),
  (730, 'Primarina', 7, 'water', 'fairy', 'Soloist Pokémon', 18, 440, 'It controls its water balloons with song. The melody is learned from others of its kind and is passed down from one generation to the next.', 729, 'Level 34'),
  (731, 'Pikipek', 7, 'normal', 'flying', 'Woodpecker Pokémon', 3, 12, 'It can peck at a rate of 16 times a second to drill holes in trees. It uses the holes for food storage and for nesting.', null, null),
  (732, 'Trumbeak', 7, 'normal', 'flying', 'Bugle Beak Pokémon', 6, 148, 'It eats berries and stores their seeds in its beak. When it encounters enemies or prey, it fires off all the seeds in a burst.', 731, 'Level 14'),
  (733, 'Toucannon', 7, 'normal', 'flying', 'Cannon Pokémon', 11, 260, 'When it battles, its beak heats up. The temperature can easily exceed 212 degrees Fahrenheit, causing severe burns when it hits.', 732, 'Level 28'),
  (734, 'Yungoos', 7, 'normal', null, 'Loitering Pokémon', 4, 60, 'With its sharp fangs, it will bite anything. It did not originally live in Alola but was imported from another region.', null, null),
  (735, 'Gumshoos', 7, 'normal', null, 'Stakeout Pokémon', 7, 142, 'When it finds a trace of its prey, it patiently stakes out the location...but it’s always snoozing by nightfall.', 734, 'Level 20 (day)'),
  (736, 'Grubbin', 7, 'bug', null, 'Larva Pokémon', 4, 44, 'Its strong jaw enables it to scrape trees and slurp out the sap. It normally lives underground.', null, null),
  (737, 'Charjabug', 7, 'bug', 'electric', 'Battery Pokémon', 5, 105, 'Its body is capable of storing electricity. On camping trips, people are grateful to have one around.', 736, 'Level 20'),
  (738, 'Vikavolt', 7, 'bug', 'electric', 'Stag Beetle Pokémon', 15, 450, 'It zips around, on sharp lookout for an opening. It concentrates electrical energy within its large jaws and uses it to zap its enemies.', 737, 'Level up at Vast Poni Canyon'),
  (739, 'Crabrawler', 7, 'fighting', null, 'Boxing Pokémon', 6, 70, 'While guarding its weak points with its pincers, it looks for an opening and unleashes punches. When it loses, it foams at the mouth and faints.', null, null),
  (740, 'Crabominable', 7, 'fighting', 'ice', 'Woolly Crab Pokémon', 17, 1800, 'It aimed for the top but got lost and ended up on a snowy mountain. Being forced to endure the cold, this Pokémon evolved and grew fur.', 739, 'Level up at Mount Lanakila'),
  (741, 'Oricorio', 7, 'fire', 'flying', 'Dancing Pokémon', 6, 34, 'It beats its wings together to create fire. As it moves in the steps of its beautiful dance, it bathes opponents in intense flames.', null, null),
  (742, 'Cutiefly', 7, 'bug', 'fairy', 'Bee Fly Pokémon', 1, 2, 'It feeds on the nectar and pollen of flowers. Because it’s able to sense auras, it can identify which flowers are about to bloom.', null, null),
  (743, 'Ribombee', 7, 'bug', 'fairy', 'Bee Fly Pokémon', 2, 5, 'It rolls up pollen into puffs. It makes many different varieties, some used as food and others used in battle.', 742, 'Level 25'),
  (744, 'Rockruff', 7, 'rock', null, 'Puppy Pokémon', 5, 92, 'It’s considered to be a good Pokémon for beginners because of its friendliness, but its disposition grows rougher as it grows up.', null, null),
  (745, 'Lycanroc', 7, 'rock', null, 'Wolf Pokémon', 8, 250, 'Its quick movements confuse its enemies. Well equipped with claws and fangs, it also uses the sharp rocks in its mane as weapons.', 744, 'Level 25 (day)'),
  (746, 'Wishiwashi', 7, 'water', null, 'Small Fry Pokémon', 2, 3, 'When it’s in trouble, its eyes moisten and begin to shine. The shining light attracts its comrades, and they stand together against their enemies.', null, null),
  (747, 'Mareanie', 7, 'poison', 'water', 'Brutal Star Pokémon', 4, 80, 'It plunges the poison spike on its head into its prey. When the prey has weakened, Mareanie deals the finishing blow with its 10 tentacles.', null, null),
  (748, 'Toxapex', 7, 'poison', 'water', 'Brutal Star Pokémon', 7, 145, 'Toxapex crawls along the ocean floor on its 12 legs. It leaves a trail of Corsola bits scattered in its wake.', 747, 'Level 38'),
  (749, 'Mudbray', 7, 'ground', null, 'Donkey Pokémon', 10, 1100, 'The mud stuck to Mudbray’s hooves enhances its grip and its powerful running gait.', null, null),
  (750, 'Mudsdale', 7, 'ground', null, 'Draft Horse Pokémon', 25, 9200, 'It spits a mud that provides resistance to both wind and rain, so the walls of old houses were often coated with it.', 749, 'Level 30'),
  (751, 'Dewpider', 7, 'water', 'bug', 'Water Bubble Pokémon', 3, 40, 'It crawls onto the land in search of food. Its water bubble allows it to breathe and protects its soft head.', null, null),
  (752, 'Araquanid', 7, 'water', 'bug', 'Water Bubble Pokémon', 18, 820, 'It delivers headbutts with the water bubble on its head. Small Pokémon get sucked into the bubble, where they drown.', 751, 'Level 22'),
  (753, 'Fomantis', 7, 'grass', null, 'Sickle Grass Pokémon', 3, 15, 'During the day, it sleeps and soaks up light. When night falls, it walks around looking for a safer place to sleep.', null, null),
  (754, 'Lurantis', 7, 'grass', null, 'Bloom Sickle Pokémon', 9, 185, 'It requires a lot of effort to maintain Lurantis’s vivid coloring, but some collectors enjoy this work and treat it as their hobby.', 753, 'Level 34 (day)'),
  (755, 'Morelull', 7, 'grass', 'fairy', 'Illuminating Pokémon', 2, 15, 'It scatters spores that flicker and glow. Anyone seeing these lights falls into a deep slumber.', null, null),
  (756, 'Shiinotic', 7, 'grass', 'fairy', 'Illuminating Pokémon', 10, 115, 'Forests where Shiinotic live are treacherous to enter at night. People confused by its strange lights can never find their way home again.', 755, 'Level 24'),
  (757, 'Salandit', 7, 'poison', 'fire', 'Toxic Lizard Pokémon', 6, 48, 'It burns its bodily fluids to create a poisonous gas. When its enemies become disoriented from inhaling the gas, it attacks them.', null, null),
  (758, 'Salazzle', 7, 'poison', 'fire', 'Toxic Lizard Pokémon', 12, 222, 'For some reason, only females have been found. It creates a reverse harem of male Salandit that it lives with.', 757, 'Level 33 (female)'),
  (759, 'Stufful', 7, 'normal', 'fighting', 'Flailing Pokémon', 5, 68, 'Despite its adorable appearance, when it gets angry and flails about, its arms and legs could knock a pro wrestler sprawling.', null, null),
  (760, 'Bewear', 7, 'normal', 'fighting', 'Strong Arm Pokémon', 21, 1350, 'This immensely dangerous Pokémon possesses overwhelming physical strength. Its habitat is generally off-limits.', 759, 'Level 27'),
  (761, 'Bounsweet', 7, 'grass', null, 'Fruit Pokémon', 3, 32, 'A delectable aroma pours from its body. They are often swallowed whole by Toucannon lured by that wafting deliciousness.', null, null),
  (762, 'Steenee', 7, 'grass', null, 'Fruit Pokémon', 7, 82, 'The sepals on its head developed to protect its body. These are quite hard, so even if pecked by bird Pokémon, this Pokémon is totally fine.', 761, 'Level 18'),
  (763, 'Tsareena', 7, 'grass', null, 'Fruit Pokémon', 12, 214, 'Its long, striking legs aren’t just for show but to be used to kick with skill. In victory, it shows off by kicking the defeated, laughing boisterously.', 762, 'Level up knowing Stomp'),
  (764, 'Comfey', 7, 'fairy', null, 'Posy Picker Pokémon', 1, 3, 'It attaches flowers to its highly nutritious vine. This revitalizes the flowers, and they give off an aromatic scent.', null, null),
  (765, 'Oranguru', 7, 'normal', 'psychic', 'Sage Pokémon', 15, 760, 'Known for its extreme intelligence, this Pokémon will look down on inexperienced Trainers, so it’s best suited to veteran Trainers.', null, null),
  (766, 'Passimian', 7, 'fighting', null, 'Teamwork Pokémon', 20, 828, 'They form groups of roughly 20 individuals. Their mutual bond is remarkable—they will never let down a comrade.', null, null),
  (767, 'Wimpod', 7, 'bug', 'water', 'Turn Tail Pokémon', 5, 120, 'This Pokémon is a coward. As it desperately dashes off, the flailing of its many legs leaves a sparkling clean path in its wake.', null, null),
  (768, 'Golisopod', 7, 'bug', 'water', 'Hard Scale Pokémon', 20, 1080, 'With a flashing slash of its giant sharp claws, it cleaves seawater—or even air—right in two.', 767, 'Level 30'),
  (769, 'Sandygast', 7, 'ghost', 'ground', 'Sand Heap Pokémon', 5, 700, 'Born from a sand mound playfully built by a child, this Pokémon embodies the grudges of the departed.', null, null),
  (770, 'Palossand', 7, 'ghost', 'ground', 'Sand Castle Pokémon', 13, 2500, 'Possessed people controlled by this Pokémon transformed its sand mound into a castle. As it evolved, its power to curse grew ever stronger.', 769, 'Level 42'),
  (771, 'Pyukumuku', 7, 'water', null, 'Sea Cucumber Pokémon', 3, 12, 'It lives in shallow seas, such as areas near a beach. It can eject its internal organs, which it uses to engulf its prey or battle enemies.', null, null),
  (772, 'Type: Null', 7, 'normal', null, 'Synthetic Pokémon', 19, 1205, 'The heavy control mask it wears suppresses its intrinsic capabilities. This Pokémon has some hidden special power.', null, null),
  (773, 'Silvally', 7, 'normal', null, 'Synthetic Pokémon', 23, 1005, 'Its trust in its partner is what awakens it. This Pokémon is capable of changing its type, a flexibility that is well displayed in battle.', 772, 'Friendship'),
  (774, 'Minior', 7, 'rock', 'flying', 'Meteor Pokémon', 3, 400, 'Originally making its home in the ozone layer, it hurtles to the ground when the shell enclosing its body grows too heavy.', null, null),
  (775, 'Komala', 7, 'normal', null, 'Drowsing Pokémon', 4, 199, 'It is born asleep, and it dies asleep. All its movements are apparently no more than the results of it tossing and turning in its dreams.', null, null),
  (776, 'Turtonator', 7, 'fire', 'dragon', 'Blast Turtle Pokémon', 20, 2120, 'The shell on its back is chemically unstable and explodes violently if struck. The hole in its stomach is its weak point.', null, null),
  (777, 'Togedemaru', 7, 'electric', 'steel', 'Roly-Poly Pokémon', 3, 33, 'The spiny fur on its back is normally at rest. When this Pokémon becomes agitated, its fur stands on end and stabs into its attackers.', null, null),
  (778, 'Mimikyu', 7, 'ghost', 'fairy', 'Disguise Pokémon', 2, 7, 'Its actual appearance is unknown. A scholar who saw what was under its rag was overwhelmed by terror and died from the shock.', null, null),
  (779, 'Bruxish', 7, 'water', 'psychic', 'Gnash Teeth Pokémon', 9, 190, 'When it unleashes its psychic power from the protuberance on its head, the grating sound of grinding teeth echoes through the area.', null, null),
  (780, 'Drampa', 7, 'normal', 'dragon', 'Placid Pokémon', 30, 1850, 'It has a compassionate personality, but if it is angered, it completely destroys its surroundings with its intense breath.', null, null),
  (781, 'Dhelmise', 7, 'ghost', 'grass', 'Sea Creeper Pokémon', 39, 2100, 'Swinging its massive anchor, it can KO Wailord in a single blow. What appears to be green seaweed is actually its body.', null, null),
  (782, 'Jangmo-o', 7, 'dragon', null, 'Scaly Pokémon', 6, 297, 'It expresses its feelings by smacking its scales. Metallic sounds echo through the tall mountains where Jangmo-o lives.', null, null),
  (783, 'Hakamo-o', 7, 'dragon', 'fighting', 'Scaly Pokémon', 12, 470, 'It leaps at its prey with a courageous shout. Its scaly punches tear its opponents to shreds.', 782, 'Level 35'),
  (784, 'Kommo-o', 7, 'dragon', 'fighting', 'Scaly Pokémon', 16, 782, 'When it spots enemies, it threatens them by jingling the scales on its tail. Weak opponents will crack and flee in panic.', 783, 'Level 45'),
  (785, 'Tapu Koko', 7, 'electric', 'fairy', 'Land Spirit Pokémon', 18, 205, 'This guardian deity of Melemele is brimming with curiosity. It summons thunderclouds and stores their lightning inside its body.', null, null),
  (786, 'Tapu Lele', 7, 'psychic', 'fairy', 'Land Spirit Pokémon', 12, 186, 'This guardian deity of Akala is guilelessly cruel. The fragrant aroma of flowers is the source of its energy.', null, null),
  (787, 'Tapu Bulu', 7, 'grass', 'fairy', 'Land Spirit Pokémon', 19, 455, 'It pulls large trees up by the roots and swings them around. It causes vegetation to grow, and then it absorbs energy from the growth.', null, null),
  (788, 'Tapu Fini', 7, 'water', 'fairy', 'Land Spirit Pokémon', 13, 212, 'The dense fog it creates brings the downfall and destruction of its confused enemies. Ocean currents are the source of its energy.', null, null),
  (789, 'Cosmog', 7, 'psychic', null, 'Nebula Pokémon', 2, 1, 'Its body is gaseous and frail. It slowly grows as it collects dust from the atmosphere.', null, null),
  (790, 'Cosmoem', 7, 'psychic', null, 'Protostar Pokémon', 1, 9999, 'Motionless as if dead, its body is faintly warm to the touch. In the distant past, it was called the cocoon of the stars.', 789, 'Level 43'),
  (791, 'Solgaleo', 7, 'psychic', 'steel', 'Sunne Pokémon', 34, 2300, 'It is said to live in another world. The intense light it radiates from the surface of its body can make the darkest of nights light up like midday.', 790, 'Level 53'),
  (792, 'Lunala', 7, 'psychic', 'ghost', 'Moone Pokémon', 40, 1200, 'It is said to be a female evolution of Cosmog. When its third eye activates, away it flies to another world.', 790, 'Level 53'),
  (793, 'Nihilego', 7, 'rock', 'poison', 'Parasite Pokémon', 12, 555, 'One of several mysterious Ultra Beasts. People on the street report observing those infested by it suddenly becoming violent.', null, null),
  (794, 'Buzzwole', 7, 'bug', 'fighting', 'Swollen Pokémon', 24, 3336, 'This Ultra Beast appeared from another world. It shows off its body, but whether that display is a boast or a threat remains unclear.', null, null),
  (795, 'Pheromosa', 7, 'bug', 'fighting', 'Lissome Pokémon', 18, 250, 'One of the dangerous Ultra Beasts, it has been spotted running across the land at terrific speeds.', null, null),
  (796, 'Xurkitree', 7, 'electric', null, 'Glowing Pokémon', 38, 1000, 'One of the mysterious life-forms known as Ultra Beasts. Astonishing electric shocks emanate from its entire body, according to witnesses.', null, null),
  (797, 'Celesteela', 7, 'steel', 'flying', 'Launch Pokémon', 92, 9999, 'It appeared from the Ultra Wormhole. Witnesses observed it flying across the sky at high speed.', null, null),
  (798, 'Kartana', 7, 'grass', 'steel', 'Drawn Sword Pokémon', 3, 1, 'This Ultra Beast came from the Ultra Wormhole. It seems not to attack enemies on its own, but its sharp body is a dangerous weapon in itself.', null, null),
  (799, 'Guzzlord', 7, 'dark', 'dragon', 'Junkivore Pokémon', 55, 8880, 'It has gobbled mountains and swallowed whole buildings, according to reports. It’s one of the Ultra Beasts.', null, null),
  (800, 'Necrozma', 7, 'psychic', null, 'Prism Pokémon', 24, 2300, 'Reminiscent of the Ultra Beasts, this life-form, apparently asleep underground, is thought to have come from another world in ancient times.', null, null),
  (801, 'Magearna', 7, 'steel', 'fairy', 'Artificial Pokémon', 10, 805, 'This artificial Pokémon, constructed more than 500 years ago, can understand human speech but cannot itself speak.', null, null),
  (802, 'Marshadow', 7, 'fighting', 'ghost', 'Gloomdweller Pokémon', 7, 222, 'Able to conceal itself in shadows, it never appears before humans, so its very existence was the stuff of myth.', null, null),
  (803, 'Poipole', 7, 'poison', null, 'Poison Pin Pokémon', 6, 18, 'This Ultra Beast is well enough liked to be chosen as a first partner in its own world.', null, null),
  (804, 'Naganadel', 7, 'poison', 'dragon', 'Poison Pin Pokémon', 36, 1500, 'It stores hundreds of liters of poisonous liquid inside its body. It is one of the organisms known as UBs.', 803, 'Level up knowing Dragon Pulse'),
  (805, 'Stakataka', 7, 'rock', 'steel', 'Rampart Pokémon', 55, 8200, 'It appeared from an Ultra Wormhole. Each one appears to be made up of many life-forms stacked one on top of each other.', null, null),
  (806, 'Blacephalon', 7, 'fire', 'ghost', 'Fireworks Pokémon', 18, 130, 'It slithers toward people. Then, without warning, it triggers the explosion of its own head. It’s apparently one kind of Ultra Beast.', null, null),
  (807, 'Zeraora', 7, 'electric', null, 'Thunderclap Pokémon', 15, 445, 'It electrifies its claws and tears its opponents apart with them. Even if they dodge its attack, they’ll be electrocuted by the flying sparks.', null, null),
  (808, 'Meltan', 7, 'steel', null, 'Hex Nut Pokémon', 2, 80, 'It melts particles of iron and other metals found in the subsoil, so it can absorb them into its body of molten steel.', null, null),
  (809, 'Melmetal', 7, 'steel', null, 'Hex Nut Pokémon', 25, 8000, 'Revered long ago for its capacity to create iron from nothing, for some reason it has come back to life after 3,000 years.', 808, 'Meltan Candies'),
  (810, 'Grookey', 8, 'grass', null, 'Chimp Pokémon', 3, 50, 'When it uses its special stick to strike up a beat, the sound waves produced carry revitalizing energy to the plants and flowers in the area.', null, null),
  (811, 'Thwackey', 8, 'grass', null, 'Beat Pokémon', 7, 140, 'The faster a Thwackey can beat out a rhythm with its two sticks, the more respect it wins from its peers.', 810, 'Level 16'),
  (812, 'Rillaboom', 8, 'grass', null, 'Drummer Pokémon', 21, 900, 'By drumming, it taps into the power of its special tree stump. The roots of the stump follow its direction in battle.', 811, 'Level 35'),
  (813, 'Scorbunny', 8, 'fire', null, 'Rabbit Pokémon', 3, 45, 'A warm-up of running around gets fire energy coursing through this Pokémon’s body. Once that happens, it’s ready to fight at full power.', null, null),
  (814, 'Raboot', 8, 'fire', null, 'Rabbit Pokémon', 6, 90, 'Its thick and fluffy fur protects it from the cold and enables it to use hotter fire moves.', 813, 'Level 16'),
  (815, 'Cinderace', 8, 'fire', null, 'Striker Pokémon', 14, 330, 'It juggles a pebble with its feet, turning it into a burning soccer ball. Its shots strike opponents hard and leave them scorched.', 814, 'Level 35'),
  (816, 'Sobble', 8, 'water', null, 'Water Lizard Pokémon', 3, 40, 'When scared, this Pokémon cries. Its tears pack the chemical punch of 100 onions, and attackers won’t be able to resist weeping.', null, null),
  (817, 'Drizzile', 8, 'water', null, 'Water Lizard Pokémon', 7, 115, 'A clever combatant, this Pokémon battles using water balloons created with moisture secreted from its palms.', 816, 'Level 16'),
  (818, 'Inteleon', 8, 'water', null, 'Secret Agent Pokémon', 19, 452, 'It has many hidden capabilities, such as fingertips that can shoot water and a membrane on its back that it can use to glide through the air.', 817, 'Level 35'),
  (819, 'Skwovet', 8, 'normal', null, 'Cheeky Pokémon', 3, 25, 'Found throughout the Galar region, this Pokémon becomes uneasy if its cheeks are ever completely empty of berries.', null, null),
  (820, 'Greedent', 8, 'normal', null, 'Greedy Pokémon', 6, 60, 'It stashes berries in its tail—so many berries that they fall out constantly. But this Pokémon is a bit slow-witted, so it doesn’t notice the loss.', 819, 'Level 24'),
  (821, 'Rookidee', 8, 'flying', null, 'Tiny Bird Pokémon', 2, 18, 'It will bravely challenge any opponent, no matter how powerful. This Pokémon benefits from every battle—even a defeat increases its strength a bit.', null, null),
  (822, 'Corvisquire', 8, 'flying', null, 'Raven Pokémon', 8, 160, 'Smart enough to use tools in battle, these Pokémon have been seen picking up rocks and flinging them or using ropes to wrap up enemies.', 821, 'Level 18'),
  (823, 'Corviknight', 8, 'flying', 'steel', 'Raven Pokémon', 22, 750, 'This Pokémon reigns supreme in the skies of the Galar region. The black luster of its steel body could drive terror into the heart of any foe.', 822, 'Level 38'),
  (824, 'Blipbug', 8, 'bug', null, 'Larva Pokémon', 4, 80, 'A constant collector of information, this Pokémon is very smart. Very strong is what it isn’t.', null, null),
  (825, 'Dottler', 8, 'bug', 'psychic', 'Radome Pokémon', 4, 195, 'It barely moves, but it’s still alive. Hiding in its shell without food or water seems to have awakened its psychic powers.', 824, 'Level 10'),
  (826, 'Orbeetle', 8, 'bug', 'psychic', 'Seven Spot Pokémon', 4, 408, 'It’s famous for its high level of intelligence, and the large size of its brain is proof that it also possesses immense psychic power.', 825, 'Level 30'),
  (827, 'Nickit', 8, 'dark', null, 'Fox Pokémon', 6, 89, 'Aided by the soft pads on its feet, it silently raids the food stores of other Pokémon. It survives off its ill-gotten gains.', null, null),
  (828, 'Thievul', 8, 'dark', null, 'Fox Pokémon', 12, 199, 'It secretly marks potential targets with a scent. By following the scent, it stalks its targets and steals from them when they least expect it.', 827, 'Level 18'),
  (829, 'Gossifleur', 8, 'grass', null, 'Flowering Pokémon', 4, 22, 'It anchors itself in the ground with its single leg, then basks in the sun. After absorbing enough sunlight, its petals spread as it blooms brilliantly.', null, null),
  (830, 'Eldegoss', 8, 'grass', null, 'Cotton Bloom Pokémon', 5, 25, 'The seeds attached to its cotton fluff are full of nutrients. It spreads them on the wind so that plants and other Pokémon can benefit from them.', 829, 'Level 20'),
  (831, 'Wooloo', 8, 'normal', null, 'Sheep Pokémon', 6, 60, 'Its curly fleece is such an effective cushion that this Pokémon could fall off a cliff and stand right back up at the bottom, unharmed.', null, null),
  (832, 'Dubwool', 8, 'normal', null, 'Sheep Pokémon', 13, 430, 'Weave a carpet from its springy wool, and you end up with something closer to a trampoline. You’ll start to bounce the moment you set foot on it.', 831, 'Level 24'),
  (833, 'Chewtle', 8, 'water', null, 'Snapping Pokémon', 3, 85, 'Apparently the itch of its teething impels it to snap its jaws at anything in front of it.', null, null),
  (834, 'Drednaw', 8, 'water', 'rock', 'Bite Pokémon', 10, 1155, 'With jaws that can shear through steel rods, this highly aggressive Pokémon chomps down on its unfortunate prey.', 833, 'Level 22'),
  (835, 'Yamper', 8, 'electric', null, 'Puppy Pokémon', 3, 135, 'This Pokémon is very popular as a herding dog in the Galar region. As it runs, it generates electricity from the base of its tail.', null, null),
  (836, 'Boltund', 8, 'electric', null, 'Dog Pokémon', 10, 340, 'This Pokémon generates electricity and channels it into its legs to keep them going strong. Boltund can run nonstop for three full days.', 835, 'Level 25'),
  (837, 'Rolycoly', 8, 'rock', null, 'Coal Pokémon', 3, 120, 'Most of its body has the same composition as coal. Fittingly, this Pokémon was first discovered in coal mines about 400 years ago.', null, null),
  (838, 'Carkol', 8, 'rock', 'fire', 'Coal Pokémon', 11, 780, 'It forms coal inside its body. Coal dropped by this Pokémon once helped fuel the lives of people in the Galar region.', 837, 'Level 18'),
  (839, 'Coalossal', 8, 'rock', 'fire', 'Coal Pokémon', 28, 3105, 'It’s usually peaceful, but the vandalism of mines enrages it. Offenders will be incinerated with flames that reach 2,700 degrees Fahrenheit.', 838, 'Level 34'),
  (840, 'Applin', 8, 'grass', 'dragon', 'Apple Core Pokémon', 2, 5, 'It spends its entire life inside an apple. It hides from its natural enemies, bird Pokémon, by pretending it’s just an apple and nothing more.', null, null),
  (841, 'Flapple', 8, 'grass', 'dragon', 'Apple Wing Pokémon', 3, 10, 'It ate a sour apple, and that induced its evolution. In its cheeks, it stores an acid capable of causing chemical burns.', 840, 'Tart Apple'),
  (842, 'Appletun', 8, 'grass', 'dragon', 'Apple Nectar Pokémon', 4, 130, 'Eating a sweet apple caused its evolution. A nectarous scent wafts from its body, luring in the bug Pokémon it preys on.', 840, 'Sweet Apple'),
  (843, 'Silicobra', 8, 'ground', null, 'Sand Snake Pokémon', 22, 76, 'As it digs, it swallows sand and stores it in its neck pouch. The pouch can hold more than 17 pounds of sand.', null, null),
  (844, 'Sandaconda', 8, 'ground', null, 'Sand Snake Pokémon', 38, 655, 'When it contracts its body, over 220 pounds of sand sprays from its nose. If it ever runs out of sand, it becomes disheartened.', 843, 'Level 36'),
  (845, 'Cramorant', 8, 'flying', 'water', 'Gulp Pokémon', 8, 180, 'It’s so strong that it can knock out some opponents in a single hit, but it also may forget what it’s battling midfight.', null, null),
  (846, 'Arrokuda', 8, 'water', null, 'Rush Pokémon', 5, 10, 'If it sees any movement around it, this Pokémon charges for it straightaway, leading with its sharply pointed jaw. It’s very proud of that jaw.', null, null),
  (847, 'Barraskewda', 8, 'water', null, 'Skewer Pokémon', 13, 300, 'This Pokémon has a jaw that’s as sharp as a spear and as strong as steel. Apparently Barraskewda’s flesh is surprisingly tasty, too.', 846, 'Level 26'),
  (848, 'Toxel', 8, 'electric', 'poison', 'Baby Pokémon', 4, 110, 'It stores poison in an internal poison sac and secretes that poison through its skin. If you touch this Pokémon, a tingling sensation follows.', null, null),
  (849, 'Toxtricity', 8, 'electric', 'poison', 'Punk Pokémon', 16, 400, 'When this Pokémon sounds as if it’s strumming a guitar, it’s actually clawing at the protrusions on its chest to generate electricity.', 848, 'Level 30'),
  (850, 'Sizzlipede', 8, 'fire', 'bug', 'Radiator Pokémon', 7, 10, 'It stores flammable gas in its body and uses it to generate heat. The yellow sections on its belly get particularly hot.', null, null),
  (851, 'Centiskorch', 8, 'fire', 'bug', 'Radiator Pokémon', 30, 1200, 'When it heats up, its body temperature reaches about 1,500 degrees Fahrenheit. It lashes its body like a whip and launches itself at enemies.', 850, 'Level 28'),
  (852, 'Clobbopus', 8, 'fighting', null, 'Tantrum Pokémon', 6, 40, 'It’s very curious, but its means of investigating things is to try to punch them with its tentacles. The search for food is what brings it onto land.', null, null),
  (853, 'Grapploct', 8, 'fighting', null, 'Jujitsu Pokémon', 16, 390, 'A body made up of nothing but muscle makes the grappling moves this Pokémon performs with its tentacles tremendously powerful.', 852, 'Level up knowing Taunt'),
  (854, 'Sinistea', 8, 'ghost', null, 'Black Tea Pokémon', 1, 2, 'This Pokémon is said to have been born when a lonely spirit possessed a cold, leftover cup of tea.', null, null),
  (855, 'Polteageist', 8, 'ghost', null, 'Black Tea Pokémon', 2, 4, 'This species lives in antique teapots. Most pots are forgeries, but on rare occasions, an authentic work is found.', 854, 'Cracked Pot'),
  (856, 'Hatenna', 8, 'psychic', null, 'Calm Pokémon', 4, 34, 'Via the protrusion on its head, it senses other creatures’ emotions. If you don’t have a calm disposition, it will never warm up to you.', null, null),
  (857, 'Hattrem', 8, 'psychic', null, 'Serene Pokémon', 6, 48, 'No matter who you are, if you bring strong emotions near this Pokémon, it will silence you violently.', 856, 'Level 32'),
  (858, 'Hatterene', 8, 'psychic', 'fairy', 'Silent Pokémon', 21, 51, 'It emits psychic power strong enough to cause headaches as a deterrent to the approach of others.', 857, 'Level 42'),
  (859, 'Impidimp', 8, 'dark', 'fairy', 'Wily Pokémon', 4, 55, 'Through its nose, it sucks in the emanations produced by people and Pokémon when they feel annoyed. It thrives off this negative energy.', null, null),
  (860, 'Morgrem', 8, 'dark', 'fairy', 'Devious Pokémon', 8, 125, 'When it gets down on all fours as if to beg for forgiveness, it’s trying to lure opponents in so that it can stab them with its spear-like hair.', 859, 'Level 32'),
  (861, 'Grimmsnarl', 8, 'dark', 'fairy', 'Bulk Up Pokémon', 15, 610, 'With the hair wrapped around its body helping to enhance its muscles, this Pokémon can overwhelm even Machamp.', 860, 'Level 42'),
  (862, 'Obstagoon', 8, 'dark', 'normal', 'Blocking Pokémon', 16, 460, 'Its voice is staggering in volume. Obstagoon has a tendency to take on a threatening posture and shout—this move is known as Obstruct.', 264, 'Level 35 (night)'),
  (863, 'Perrserker', 8, 'steel', null, 'Viking Pokémon', 8, 280, 'What appears to be an iron helmet is actually hardened hair. This Pokémon lives for the thrill of battle.', 52, 'Level 28'),
  (864, 'Cursola', 8, 'ghost', null, 'Coral Pokémon', 10, 4, 'Its shell is overflowing with its heightened otherworldly energy. The ectoplasm serves as protection for this Pokémon’s core spirit.', 222, 'Level 38'),
  (865, 'Sirfetch''d', 8, 'fighting', null, 'Wild Duck Pokémon', 8, 1170, 'Only Farfetch’d that have survived many battles can attain this evolution. When this Pokémon’s leek withers, it will retire from combat.', 83, 'Three Critical Hits'),
  (866, 'Mr. Rime', 8, 'ice', 'psychic', 'Comedian Pokémon', 15, 582, 'It’s highly skilled at tap-dancing. It waves its cane of ice in time with its graceful movements.', 122, 'Level 42'),
  (867, 'Runerigus', 8, 'ground', 'ghost', 'Grudge Pokémon', 16, 666, 'A powerful curse was woven into an ancient painting. After absorbing the spirit of a Yamask, the painting began to move.', 562, 'Take Damage'),
  (868, 'Milcery', 8, 'fairy', null, 'Cream Pokémon', 2, 3, 'This Pokémon was born from sweet-smelling particles in the air. Its body is made of cream.', null, null),
  (869, 'Alcremie', 8, 'fairy', null, 'Cream Pokémon', 3, 5, 'When it trusts a Trainer, it will treat them to berries it’s decorated with cream.', 868, 'Spin (day)'),
  (870, 'Falinks', 8, 'fighting', null, 'Formation Pokémon', 30, 620, 'Five of them are troopers, and one is the brass. The brass’s orders are absolute.', null, null),
  (871, 'Pincurchin', 8, 'electric', null, 'Sea Urchin Pokémon', 3, 10, 'It feeds on seaweed, using its teeth to scrape it off rocks. Electric current flows from the tips of its spines.', null, null),
  (872, 'Snom', 8, 'ice', 'bug', 'Worm Pokémon', 3, 38, 'It spits out thread imbued with a frigid sort of energy and uses it to tie its body to branches, disguising itself as an icicle while it sleeps.', null, null),
  (873, 'Frosmoth', 8, 'ice', 'bug', 'Frost Moth Pokémon', 13, 420, 'Icy scales fall from its wings like snow as it flies over fields and mountains. The temperature of its wings is less than −290 degrees Fahrenheit.', 872, 'Friendship (night)'),
  (874, 'Stonjourner', 8, 'rock', null, 'Big Rock Pokémon', 25, 5200, 'It stands in grasslands, watching the sun’s descent from zenith to horizon. This Pokémon has a talent for delivering dynamic kicks.', null, null),
  (875, 'Eiscue', 8, 'ice', null, 'Penguin Pokémon', 14, 890, 'It drifted in on the flow of ocean waters from a frigid place. It keeps its head iced constantly to make sure it stays nice and cold.', null, null),
  (876, 'Indeedee', 8, 'psychic', 'normal', 'Emotion Pokémon', 9, 280, 'It uses the horns on its head to sense the emotions of others. Males will act as valets for those they serve, looking after their every need.', null, null),
  (877, 'Morpeko', 8, 'electric', 'dark', 'Two-Sided Pokémon', 3, 30, 'As it eats the seeds stored up in its pocket-like pouches, this Pokémon is not just satisfying its constant hunger. It’s also generating electricity.', null, null),
  (878, 'Cufant', 8, 'steel', null, 'Copperderm Pokémon', 12, 1000, 'It digs up the ground with its trunk. It’s also very strong, being able to carry loads of over five tons without any problem at all.', null, null),
  (879, 'Copperajah', 8, 'steel', null, 'Copperderm Pokémon', 30, 6500, 'They came over from another region long ago and worked together with humans. Their green skin is resistant to water.', 878, 'Level 34'),
  (880, 'Dracozolt', 8, 'electric', 'dragon', 'Fossil Pokémon', 18, 1900, 'In ancient times, it was unbeatable thanks to its powerful lower body, but it went extinct anyway after it depleted all its plant-based food sources.', null, null),
  (881, 'Arctozolt', 8, 'electric', 'ice', 'Fossil Pokémon', 23, 1500, 'The shaking of its freezing upper half is what generates its electricity. It has a hard time walking around.', null, null),
  (882, 'Dracovish', 8, 'water', 'dragon', 'Fossil Pokémon', 23, 2150, 'Powerful legs and jaws made it the apex predator of its time. Its own overhunting of its prey was what drove it to extinction.', null, null),
  (883, 'Arctovish', 8, 'water', 'ice', 'Fossil Pokémon', 20, 1750, 'Though it’s able to capture prey by freezing its surroundings, it has trouble eating the prey afterward because its mouth is on top of its head.', null, null),
  (884, 'Duraludon', 8, 'steel', 'dragon', 'Alloy Pokémon', 18, 400, 'Its body resembles polished metal, and it’s both lightweight and strong. The only drawback is that it rusts easily.', null, null),
  (885, 'Dreepy', 8, 'dragon', 'ghost', 'Lingering Pokémon', 5, 20, 'After being reborn as a ghost Pokémon, Dreepy wanders the areas it used to inhabit back when it was alive in prehistoric seas.', null, null),
  (886, 'Drakloak', 8, 'dragon', 'ghost', 'Caretaker Pokémon', 14, 110, 'It’s capable of flying faster than 120 mph. It battles alongside Dreepy and dotes on them until they successfully evolve.', 885, 'Level 50'),
  (887, 'Dragapult', 8, 'dragon', 'ghost', 'Stealth Pokémon', 30, 500, 'When it isn’t battling, it keeps Dreepy in the holes on its horns. Once a fight starts, it launches the Dreepy like supersonic missiles.', 886, 'Level 60'),
  (888, 'Zacian', 8, 'fairy', null, 'Warrior Pokémon', 28, 1100, 'Known as a legendary hero, this Pokémon absorbs metal particles, transforming them into a weapon it uses to battle.', null, null),
  (889, 'Zamazenta', 8, 'fighting', null, 'Warrior Pokémon', 29, 2100, 'In times past, it worked together with a king of the people to save the Galar region. It absorbs metal that it then uses in battle.', null, null),
  (890, 'Eternatus', 8, 'poison', 'dragon', 'Gigantic Pokémon', 200, 9500, 'The core on its chest absorbs energy emanating from the lands of the Galar region. This energy is what allows Eternatus to stay active.', null, null),
  (891, 'Kubfu', 8, 'fighting', null, 'Wushu Pokémon', 6, 120, 'Kubfu trains hard to perfect its moves. The moves it masters will determine which form it takes when it evolves.', null, null),
  (892, 'Urshifu', 8, 'fighting', 'dark', 'Wushu Pokémon', 19, 1050, 'This form of Urshifu is a strong believer in the one-hit KO. Its strategy is to leap in close to foes and land a devastating blow with a hardened fist.', 891, 'Tower Of Darkness'),
  (893, 'Zarude', 8, 'dark', 'grass', 'Rogue Monkey Pokémon', 18, 700, 'Within dense forests, this Pokémon lives in a pack with others of its kind. It’s incredibly aggressive, and the other Pokémon of the forest fear it.', null, null),
  (894, 'Regieleki', 8, 'electric', null, 'Electron Pokémon', 12, 1450, 'This Pokémon is a cluster of electrical energy. It’s said that removing the rings on Regieleki’s body will unleash the Pokémon’s latent power.', null, null),
  (895, 'Regidrago', 8, 'dragon', null, 'Dragon Orb Pokémon', 21, 2000, 'An academic theory proposes that Regidrago’s arms were once the head of an ancient dragon Pokémon. The theory remains unproven.', null, null),
  (896, 'Glastrier', 8, 'ice', null, 'Wild Horse Pokémon', 22, 8000, 'Glastrier emits intense cold from its hooves. It’s also a belligerent Pokémon—anything it wants, it takes by force.', null, null),
  (897, 'Spectrier', 8, 'ghost', null, 'Swift Horse Pokémon', 20, 445, 'It probes its surroundings with all its senses save one—it doesn’t use its sense of sight. Spectrier’s kicks are said to separate soul from body.', null, null),
  (898, 'Calyrex', 8, 'psychic', 'grass', 'King Pokémon', 11, 77, 'Calyrex is a merciful Pokémon, capable of providing healing and blessings. It reigned over the Galar region in times of yore.', null, null),
  (899, 'Wyrdeer', 8, 'normal', 'psychic', 'Big Horn Pokémon', 18, 951, 'The black orbs shine with an uncanny light when the Pokémon is erecting invisible barriers. The fur shed from its beard retains heat well and is a highly useful material for winter clothing.', 234, 'Agile Style Move'),
  (900, 'Kleavor', 8, 'bug', 'rock', 'Axe Pokémon', 18, 890, 'A violent creature that fells towering trees with its crude axes and shields itself with hard stone. If one should chance upon this Pokémon in the wilds, one''s only recourse is to flee.', 123, 'Black Augurite'),
  (901, 'Ursaluna', 8, 'ground', 'normal', 'Peat Pokémon', 24, 2900, 'I believe it was Hisui''s swampy terrain that gave Ursaluna its burly physique and newfound capacity to manipulate peat at will.', 217, 'Peat Block (full-moon)'),
  (902, 'Basculegion', 8, 'water', 'ghost', 'Big Fish Pokémon', 30, 1100, 'Clads itself in the souls of comrades that perished before fulfilling their goals of journeying upstream. No other species throughout all Hisui''s rivers is Basculegion''s equal.', 550, 'Recoil Damage (male)'),
  (903, 'Sneasler', 8, 'fighting', 'poison', 'Free Climb Pokémon', 13, 430, 'Because of Sneasler''s virulent poison and daunting physical prowess, no other species could hope to best it on the frozen highlands. Preferring solitude, this species does not form packs.', 215, 'Level up holding Razor Claw (day)'),
  (904, 'Overqwil', 8, 'dark', 'poison', 'Pin Cluster Pokémon', 25, 605, 'Its lancelike spikes and savage temperament have earned it the nickname ”sea fiend.” It slurps up poison to nourish itself.', 211, 'Strong Style Move'),
  (905, 'Enamorus', 8, 'fairy', 'flying', 'Love-Hate Pokémon', 16, 480, 'When it flies to this land from across the sea, the bitter winter comes to an end. According to legend, this Pokémon''s love gives rise to the budding of fresh life across Hisui.', null, null),
  (906, 'Sprigatito', 9, 'grass', null, 'Grass Cat Pokémon', 4, 41, 'Its fluffy fur is similar in composition to plants. This Pokémon frequently washes its face to keep it from drying out.', null, null),
  (907, 'Floragato', 9, 'grass', null, 'Grass Cat Pokémon', 9, 122, 'Floragato deftly wields the vine hidden beneath its long fur, slamming the hard flower bud against its opponents.', 906, 'Level 16'),
  (908, 'Meowscarada', 9, 'grass', 'dark', 'Magician Pokémon', 15, 312, 'This Pokémon uses the reflective fur lining its cape to camouflage the stem of its flower, creating the illusion that the flower is floating.', 907, 'Level 36'),
  (909, 'Fuecoco', 9, 'fire', null, 'Fire Croc Pokémon', 4, 98, 'It lies on warm rocks and uses the heat absorbed by its square-shaped scales to create fire energy.', null, null),
  (910, 'Crocalor', 9, 'fire', null, 'Fire Croc Pokémon', 10, 307, 'The combination of Crocalor’s fire energy and overflowing vitality has caused an egg-shaped fireball to appear on the Pokémon’s head.', 909, 'Level 16'),
  (911, 'Skeledirge', 9, 'fire', 'ghost', 'Singer Pokémon', 16, 3265, 'The fiery bird changes shape when Skeledirge sings. Rumor has it that the bird was born when the fireball on Skeledirge’s head gained a soul.', 910, 'Level 36'),
  (912, 'Quaxly', 9, 'water', null, 'Duckling Pokémon', 5, 61, 'This Pokémon migrated to Paldea from distant lands long ago. The gel secreted by its feathers repels water and grime.', null, null),
  (913, 'Quaxwell', 9, 'water', null, 'Practicing Pokémon', 12, 215, 'These Pokémon constantly run through shallow waters to train their legs, then compete with each other to see which of them kicks most gracefully.', 912, 'Level 16'),
  (914, 'Quaquaval', 9, 'water', 'fighting', 'Dancer Pokémon', 18, 619, 'A single kick from a Quaquaval can send a truck rolling. This Pokémon uses its powerful legs to perform striking dances from far-off lands.', 913, 'Level 36'),
  (915, 'Lechonk', 9, 'normal', null, 'Hog Pokémon', 5, 102, 'It searches for food all day. It possesses a keen sense of smell but doesn’t use it for anything other than foraging.', null, null),
  (916, 'Oinkologne', 9, 'normal', null, 'Hog Pokémon', 10, 1200, 'Oinkologne is proud of its fine, glossy skin. It emits a concentrated scent from the tip of its tail.', 915, 'Level 18 (male)'),
  (917, 'Tarountula', 9, 'bug', null, 'String Ball Pokémon', 3, 40, 'The ball of threads wrapped around its body is elastic enough to deflect the scythes of Scyther, this Pokémon’s natural enemy.', null, null),
  (918, 'Spidops', 9, 'bug', null, 'Trap Pokémon', 10, 165, 'It clings to branches and ceilings using its threads and moves without a sound. It takes out its prey before the prey even notices it.', 917, 'Level 15'),
  (919, 'Nymble', 9, 'bug', null, 'Grasshopper Pokémon', 2, 10, 'It has its third set of legs folded up. When it’s in a tough spot, this Pokémon jumps over 30 feet using the strength of its legs.', null, null),
  (920, 'Lokix', 9, 'bug', 'dark', 'Grasshopper Pokémon', 10, 175, 'When it decides to fight all out, it stands on its previously folded legs to enter Showdown Mode. It neutralizes its enemies in short order.', 919, 'Level 24'),
  (921, 'Pawmi', 9, 'electric', null, 'Mouse Pokémon', 3, 25, 'It has underdeveloped electric sacs on its cheeks. These sacs can produce electricity only if Pawmi rubs them furiously with the pads on its forepaws.', null, null),
  (922, 'Pawmo', 9, 'electric', 'fighting', 'Mouse Pokémon', 4, 65, 'When its group is attacked, Pawmo is the first to leap into battle, defeating enemies with a fighting technique that utilizes electric shocks.', 921, 'Level 18'),
  (923, 'Pawmot', 9, 'electric', 'fighting', 'Hands-On Pokémon', 9, 410, 'This Pokémon normally is slow to react, but once it enters battle, it will strike down its enemies with lightning-fast movements.', 922, 'Level up'),
  (924, 'Tandemaus', 9, 'normal', null, 'Couple Pokémon', 3, 18, 'Exhibiting great teamwork, they use their incisors to cut pieces out of any material that might be useful for a nest, then make off with them.', null, null),
  (925, 'Maushold', 9, 'normal', null, 'Family Pokémon', 3, 28, 'The two little ones just appeared one day. The group might be a family of related Pokémon, but nobody knows for sure.', 924, 'In Battle Level Up'),
  (926, 'Fidough', 9, 'fairy', null, 'Puppy Pokémon', 3, 109, 'This Pokémon is smooth and moist to the touch. Yeast in Fidough’s breath induces fermentation in the Pokémon’s vicinity.', null, null),
  (927, 'Dachsbun', 9, 'fairy', null, 'Dog Pokémon', 5, 149, 'The pleasant aroma that emanates from this Pokémon’s body helps wheat grow, so Dachsbun has been treasured by farming villages.', 926, 'Level 26'),
  (928, 'Smoliv', 9, 'grass', 'normal', 'Olive Pokémon', 3, 65, 'It protects itself from enemies by emitting oil from the fruit on its head. This oil is bitter and astringent enough to make someone flinch.', null, null),
  (929, 'Dolliv', 9, 'grass', 'normal', 'Olive Pokémon', 6, 119, 'Dolliv shares its tasty, fresh-scented oil with others. This species has coexisted with humans since times long gone.', 928, 'Level 25'),
  (930, 'Arboliva', 9, 'grass', 'normal', 'Olive Pokémon', 14, 482, 'This calm Pokémon is very compassionate. It will share its delicious, nutrient-rich oil with weakened Pokémon.', 929, 'Level 35'),
  (931, 'Squawkabilly', 9, 'normal', 'flying', 'Parrot Pokémon', 6, 24, 'These Pokémon prefer to live in cities. They form flocks based on the color of their feathers, and they fight over territory.', null, null),
  (932, 'Nacli', 9, 'rock', null, 'Rock Salt Pokémon', 4, 160, 'It was born in a layer of rock salt deep under the earth. This species was particularly treasured in the old days, as they would share precious salt.', null, null),
  (933, 'Naclstack', 9, 'rock', null, 'Rock Salt Pokémon', 6, 1050, 'This Pokémon dry cures its prey by spraying salt over them. The curing process steals away the water in the prey’s body.', 932, 'Level 24'),
  (934, 'Garganacl', 9, 'rock', null, 'Rock Salt Pokémon', 23, 2400, 'Garganacl will rub its fingertips together and sprinkle injured Pokémon with salt. Even severe wounds will promptly heal afterward.', 933, 'Level 38'),
  (935, 'Charcadet', 9, 'fire', null, 'Fire Child Pokémon', 6, 105, 'Burnt charcoal came to life and became a Pokémon. Possessing a fiery fighting spirit, Charcadet will battle even tough opponents.', null, null),
  (936, 'Armarouge', 9, 'fire', 'psychic', 'Fire Warrior Pokémon', 15, 850, 'Armarouge evolved through the use of a set of armor that belonged to a distinguished warrior. This Pokémon is incredibly loyal.', 935, 'Auspicious Armor'),
  (937, 'Ceruledge', 9, 'fire', 'ghost', 'Fire Blades Pokémon', 16, 620, 'The fiery blades on its arms burn fiercely with the lingering resentment of a sword wielder who fell before accomplishing their goal.', 935, 'Malicious Armor'),
  (938, 'Tadbulb', 9, 'electric', null, 'EleTadpole Pokémon', 3, 4, 'Tadbulb shakes its tail to generate electricity. If it senses danger, it will make its head blink on and off to alert its allies.', null, null),
  (939, 'Bellibolt', 9, 'electric', null, 'EleFrog Pokémon', 12, 1130, 'When this Pokémon expands and contracts its wobbly body, the belly-button dynamo in its stomach produces a huge amount of electricity.', 938, 'Thunder Stone'),
  (940, 'Wattrel', 9, 'electric', 'flying', 'Storm Petrel Pokémon', 4, 36, 'When its wings catch the wind, the bones within produce electricity. This Pokémon dives into the ocean, catching prey by electrocuting them.', null, null),
  (941, 'Kilowattrel', 9, 'electric', 'flying', 'Frigatebird Pokémon', 14, 386, 'Kilowattrel inflates its throat sac to amplify its electricity. By riding the wind, this Pokémon can fly over 430 miles in a day.', 940, 'Level 25'),
  (942, 'Maschiff', 9, 'dark', null, 'Rascal Pokémon', 5, 160, 'It always scowls in an attempt to make opponents take it seriously, but even crying children will burst into laughter when they see Maschiff’s face.', null, null),
  (943, 'Mabosstiff', 9, 'dark', null, 'Boss Pokémon', 11, 610, 'This Pokémon can store energy in its large dewlap. Mabosstiff unleashes this energy all at once to blow away enemies.', 942, 'Level 30'),
  (944, 'Shroodle', 9, 'poison', 'normal', 'Toxic Mouse Pokémon', 2, 7, 'Though usually a mellow Pokémon, it will sink its sharp, poison-soaked front teeth into any that anger it, causing paralysis in the object of its ire.', null, null),
  (945, 'Grafaiai', 9, 'poison', 'normal', 'Toxic Monkey Pokémon', 7, 272, 'The color of the poisonous saliva depends on what the Pokémon eats. Grafaiai covers its fingers in its saliva and draws patterns on trees in forests.', 944, 'Level 28'),
  (946, 'Bramblin', 9, 'grass', 'ghost', 'Tumbleweed Pokémon', 6, 6, 'A soul unable to move on to the afterlife was blown around by the wind until it got tangled up with dried grass and became a Pokémon.', null, null),
  (947, 'Brambleghast', 9, 'grass', 'ghost', 'Tumbleweed Pokémon', 12, 60, 'It will open the branches of its head to envelop its prey. Once it absorbs all the life energy it needs, it expels the prey and discards it.', 946, 'Level up'),
  (948, 'Toedscool', 9, 'ground', 'grass', 'Woodear Pokémon', 9, 330, 'Toedscool lives in muggy forests. The flaps that fall from its body are chewy and very delicious.', null, null),
  (949, 'Toedscruel', 9, 'ground', 'grass', 'Woodear Pokémon', 19, 580, 'These Pokémon gather into groups and form colonies deep within forests. They absolutely hate it when strangers approach.', 948, 'Level 30'),
  (950, 'Klawf', 9, 'rock', null, 'Ambush Pokémon', 13, 790, 'Klawf hangs upside-down from cliffs, waiting for prey. But Klawf can’t remain in this position for long because its blood rushes to its head.', null, null),
  (951, 'Capsakid', 9, 'grass', null, 'Spicy Pepper Pokémon', 3, 30, 'The more sunlight this Pokémon bathes in, the more spicy chemicals are produced by its body, and thus the spicier its moves become.', null, null),
  (952, 'Scovillain', 9, 'grass', 'fire', 'Spicy Pepper Pokémon', 9, 150, 'The red head converts spicy chemicals into fire energy and blasts the surrounding area with a super spicy stream of flame.', 951, 'Fire Stone'),
  (953, 'Rellor', 9, 'bug', null, 'Rolling Pokémon', 2, 10, 'This Pokémon creates a mud ball by mixing sand and dirt with psychic energy. It treasures its mud ball more than its own life.', null, null),
  (954, 'Rabsca', 9, 'bug', 'psychic', 'Rolling Pokémon', 3, 35, 'The body that supports the ball barely moves. Therefore, it is thought that the true body of this Pokémon is actually inside the ball.', 953, 'Level up'),
  (955, 'Flittle', 9, 'psychic', null, 'Frill Pokémon', 2, 15, 'Flittle’s toes levitate about half an inch above the ground because of the psychic power emitted from the frills on the Pokémon’s belly.', null, null),
  (956, 'Espathra', 9, 'psychic', null, 'Ostrich Pokémon', 19, 900, 'It immobilizes opponents by bathing them in psychic power from its large eyes. Despite its appearance, it has a vicious temperament.', 955, 'Level 35'),
  (957, 'Tinkatink', 9, 'fairy', 'steel', 'Metalsmith Pokémon', 4, 89, 'It swings its handmade hammer around to protect itself, but the hammer is often stolen by Pokémon that eat metal.', null, null),
  (958, 'Tinkatuff', 9, 'fairy', 'steel', 'Hammer Pokémon', 7, 591, 'This Pokémon will attack groups of Pawniard and Bisharp, gathering metal from them in order to create a large and sturdy hammer.', 957, 'Level 24'),
  (959, 'Tinkaton', 9, 'fairy', 'steel', 'Hammer Pokémon', 7, 1128, 'This intelligent Pokémon has a very daring disposition. It knocks rocks into the sky with its hammer, aiming for flying Corviknight.', 958, 'Level 38'),
  (960, 'Wiglett', 9, 'water', null, 'Garden Eel Pokémon', 12, 18, 'This Pokémon can pick up the scent of a Veluza just over 65 feet away and will hide itself in the sand.', null, null),
  (961, 'Wugtrio', 9, 'water', null, 'Garden Eel Pokémon', 12, 54, 'It has a vicious temperament, contrary to what its appearance may suggest. It wraps its long bodies around prey, then drags the prey into its den.', 960, 'Level 26'),
  (962, 'Bombirdier', 9, 'flying', 'dark', 'Item Drop Pokémon', 15, 429, 'It gathers things up in an apron made from shed feathers added to the Pokémon’s chest feathers, then drops those things from high places for fun.', null, null),
  (963, 'Finizen', 9, 'water', null, 'Dolphin Pokémon', 13, 602, 'It likes playing with others of its kind using the water ring on its tail. It uses ultrasonic waves to sense the emotions of other living creatures.', null, null),
  (964, 'Palafin', 9, 'water', null, 'Dolphin Pokémon', 13, 602, 'This Pokémon changes its appearance if it hears its allies calling for help. Palafin will never show anybody its moment of transformation.', 963, 'Level 38'),
  (965, 'Varoom', 9, 'steel', 'poison', 'Single-Cyl Pokémon', 10, 350, 'It is said that this Pokémon was born when an unknown poison Pokémon entered and inspirited an engine left at a scrap-processing factory.', null, null),
  (966, 'Revavroom', 9, 'steel', 'poison', 'Multi-Cyl Pokémon', 18, 1200, 'It creates a gas out of poison and minerals from rocks. It then detonates the gas in its cylinders—now numbering eight—to generate energy.', 965, 'Level 40'),
  (967, 'Cyclizar', 9, 'dragon', 'normal', 'Mount Pokémon', 16, 630, 'Apparently Cyclizar has been allowing people to ride on its back since ancient times. Depictions of this have been found in 10,000-year-old murals.', null, null),
  (968, 'Orthworm', 9, 'steel', null, 'Earthworm Pokémon', 25, 3100, 'When attacked, this Pokémon will wield the tendrils on its body like fists and pelt the opponent with a storm of punches.', null, null),
  (969, 'Glimmet', 9, 'rock', 'poison', 'Ore Pokémon', 7, 80, 'It absorbs nutrients from cave walls. The petals it wears are made of crystallized poison.', null, null),
  (970, 'Glimmora', 9, 'rock', 'poison', 'Ore Pokémon', 15, 450, 'When this Pokémon detects danger, it will open up its crystalline petals and fire beams from its conical body.', 969, 'Level 35'),
  (971, 'Greavard', 9, 'ghost', null, 'Ghost Dog Pokémon', 6, 350, 'It is said that a dog Pokémon that died in the wild without ever interacting with a human was reborn as this Pokémon.', null, null),
  (972, 'Houndstone', 9, 'ghost', null, 'Ghost Dog Pokémon', 20, 150, 'Houndstone spends most of its time sleeping in graveyards. Among all the dog Pokémon, this one is most loyal to its master.', 971, 'Level 30 (night)'),
  (973, 'Flamigo', 9, 'flying', 'fighting', 'Synchronize Pokémon', 16, 370, 'This Pokémon apparently ties the base of its neck into a knot so that energy stored in its belly does not escape from its beak.', null, null),
  (974, 'Cetoddle', 9, 'ice', null, 'Terra Whale Pokémon', 12, 450, 'This species left the ocean and began living on land a very long time ago. It seems to be closely related to Wailmer.', null, null),
  (975, 'Cetitan', 9, 'ice', null, 'Terra Whale Pokémon', 45, 7000, 'This Pokémon wanders around snowy, icy areas. It protects its body with powerful muscles and a thick layer of fat under its skin.', 974, 'Ice Stone'),
  (976, 'Veluza', 9, 'water', 'psychic', 'Jettison Pokémon', 25, 900, 'When Veluza discards unnecessary flesh, its mind becomes honed and its psychic power increases. The spare flesh has a mild but delicious flavor.', null, null),
  (977, 'Dondozo', 9, 'water', null, 'Big Catfish Pokémon', 120, 2200, 'This Pokémon is a glutton, but it’s bad at getting food. It teams up with a Tatsugiri to catch prey.', null, null),
  (978, 'Tatsugiri', 9, 'dragon', 'water', 'Mimicry Pokémon', 3, 80, 'This is a small dragon Pokémon. It lives inside the mouth of Dondozo to protect itself from enemies on the outside.', null, null),
  (979, 'Annihilape', 9, 'fighting', 'ghost', 'Rage Monkey Pokémon', 12, 560, 'When its anger rose beyond a critical point, this Pokémon gained power that is unfettered by the limits of its physical body.', 57, 'Use Rage Fist 20 times'),
  (980, 'Clodsire', 9, 'poison', 'ground', 'Spiny Fish Pokémon', 18, 2230, 'When attacked, this Pokémon will retaliate by sticking thick spines out from its body. It’s a risky move that puts everything on the line.', 194, 'Level 20'),
  (981, 'Farigiraf', 9, 'normal', 'psychic', 'Long Neck Pokémon', 32, 1600, 'Now that the brain waves from the head and tail are synced up, the psychic power of this Pokémon is 10 times stronger than Girafarig’s.', 203, 'Level up knowing Twin Beam'),
  (982, 'Dudunsparce', 9, 'normal', null, 'Land Snake Pokémon', 36, 392, 'This Pokémon uses its hard tail to make its nest by boring holes into bedrock deep underground. The nest can reach lengths of over six miles.', 206, 'Level up knowing Hyper Drill'),
  (983, 'Kingambit', 9, 'dark', 'steel', 'Big Blade Pokémon', 20, 1200, 'Only a Bisharp that stands above all others in its vast army can evolve into Kingambit.', 625, 'Three Defeated Bisharp'),
  (984, 'Great Tusk', 9, 'ground', 'fighting', 'Paradox Pokémon', 22, 3200, 'Sightings of this Pokémon have occurred in recent years. The name Great Tusk was taken from a creature listed in a certain book.', null, null),
  (985, 'Scream Tail', 9, 'fairy', 'psychic', 'Paradox Pokémon', 12, 80, 'There has been only one reported sighting of this Pokémon. It resembles a mysterious creature depicted in an old expedition journal.', null, null),
  (986, 'Brute Bonnet', 9, 'grass', 'dark', 'Paradox Pokémon', 12, 210, 'It is possible that the creature listed as Brute Bonnet in a certain book could actually be this Pokémon.', null, null),
  (987, 'Flutter Mane', 9, 'ghost', 'fairy', 'Paradox Pokémon', 14, 40, 'This Pokémon has characteristics similar to those of Flutter Mane, a creature mentioned in a certain book.', null, null),
  (988, 'Slither Wing', 9, 'bug', 'fighting', 'Paradox Pokémon', 32, 920, 'This mysterious Pokémon has some similarities to a creature that an old book introduced as Slither Wing.', null, null),
  (989, 'Sandy Shocks', 9, 'electric', 'ground', 'Paradox Pokémon', 23, 600, 'No records exist of this Pokémon being caught. Data is lacking, but the Pokémon’s traits match up with a creature shown in an expedition journal.', null, null),
  (990, 'Iron Treads', 9, 'ground', 'steel', 'Paradox Pokémon', 9, 2400, 'This Pokémon closely resembles a scientific weapon that a paranormal magazine claimed was sent to this planet by aliens.', null, null),
  (991, 'Iron Bundle', 9, 'ice', 'water', 'Paradox Pokémon', 6, 110, 'Its shape is similar to a robot featured in a paranormal magazine article. The robot was said to have been created by an ancient civilization.', null, null),
  (992, 'Iron Hands', 9, 'fighting', 'electric', 'Paradox Pokémon', 18, 3807, 'It is very similar to a cyborg covered exclusively by a paranormal magazine. The cyborg was said to be the modified form of a certain athlete.', null, null),
  (993, 'Iron Jugulis', 9, 'dark', 'flying', 'Paradox Pokémon', 13, 1110, 'It resembles a certain Pokémon introduced in a paranormal magazine, described as the offspring of a Hydreigon that fell in love with a robot.', null, null),
  (994, 'Iron Moth', 9, 'fire', 'poison', 'Paradox Pokémon', 12, 360, 'This Pokémon resembles an unknown object described in a paranormal magazine as a UFO sent to observe humanity.', null, null),
  (995, 'Iron Thorns', 9, 'rock', 'electric', 'Paradox Pokémon', 16, 3030, 'It has some similarities to a Pokémon introduced in a dubious magazine as a Tyranitar from one billion years into the future.', null, null),
  (996, 'Frigibax', 9, 'dragon', 'ice', 'Ice Fin Pokémon', 5, 170, 'Frigibax absorbs heat through its dorsal fin and converts the heat into ice energy. The higher the temperature, the more energy Frigibax stores.', null, null),
  (997, 'Arctibax', 9, 'dragon', 'ice', 'Ice Fin Pokémon', 8, 300, 'Arctibax freezes the air around it, protecting its face with an ice mask and turning its dorsal fin into a blade of ice.', 996, 'Level 35'),
  (998, 'Baxcalibur', 9, 'dragon', 'ice', 'Ice Dragon Pokémon', 21, 2100, 'This Pokémon blasts cryogenic air out from its mouth. This air can instantly freeze even liquid-hot lava.', 997, 'Level 54'),
  (999, 'Gimmighoul', 9, 'ghost', null, 'Coin Chest Pokémon', 3, 50, 'This Pokémon was born inside a treasure chest about 1,500 years ago. It sucks the life-force out of scoundrels who try to steal the treasure.', null, null),
  (1000, 'Gholdengo', 9, 'steel', 'ghost', 'Coin Entity Pokémon', 12, 300, 'Its body seems to be made up of 1,000 coins. This Pokémon gets along well with others and is quick to make friends with anybody.', 999, 'Gimmighoul Coins'),
  (1001, 'Wo-Chien', 9, 'dark', 'grass', 'Ruinous Pokémon', 15, 742, 'The grudge of a person punished for writing the king’s evil deeds upon wooden tablets has clad itself in dead leaves to become a Pokémon.', null, null),
  (1002, 'Chien-Pao', 9, 'dark', 'ice', 'Ruinous Pokémon', 19, 1522, 'This Pokémon can control 100 tons of fallen snow. It plays around innocently by leaping in and out of avalanches it has caused.', null, null),
  (1003, 'Ting-Lu', 9, 'dark', 'ground', 'Ruinous Pokémon', 27, 6997, 'The fear poured into an ancient ritual vessel has clad itself in rocks and dirt to become a Pokémon.', null, null),
  (1004, 'Chi-Yu', 9, 'dark', 'fire', 'Ruinous Pokémon', 4, 49, 'It controls flames burning at over 5,400 degrees Fahrenheit. It casually swims through the sea of lava it creates by melting rock and sand.', null, null),
  (1005, 'Roaring Moon', 9, 'dragon', 'dark', 'Paradox Pokémon', 20, 3800, 'It is possible that this is the creature listed as Roaring Moon in an expedition journal that still holds many mysteries.', null, null),
  (1006, 'Iron Valiant', 9, 'fairy', 'fighting', 'Paradox Pokémon', 14, 350, 'It has some similarities to a mad scientist’s invention covered in a paranormal magazine.', null, null),
  (1007, 'Koraidon', 9, 'fighting', 'dragon', 'Paradox Pokémon', 25, 3030, 'This seems to be the Winged King mentioned in an old expedition journal. It was said to have split the land with its bare fists.', null, null),
  (1008, 'Miraidon', 9, 'electric', 'dragon', 'Paradox Pokémon', 35, 2400, 'Much remains unknown about this creature. It resembles Cyclizar, but it is far more ruthless and powerful.', null, null),
  (1009, 'Walking Wake', 9, 'water', 'dragon', 'Paradox Pokémon', 35, 2800, 'This ferocious creature is shrouded in mystery. It''s named after an aquatic monster mentioned in an old expedition journal.', null, null),
  (1010, 'Iron Leaves', 9, 'grass', 'psychic', 'Paradox Pokémon', 15, 1250, 'Many of its physical characteristics match those of a Virizion from the future that was covered in a paranormal magazine.', null, null),
  (1011, 'Dipplin', 9, 'grass', 'dragon', 'Candy Apple Pokémon', 4, 97, 'Dipplin is two creatures in one Pokémon. Its evolution was triggered by a special apple grown only in one place.', 840, 'Syrupy Apple'),
  (1012, 'Poltchageist', 9, 'grass', 'ghost', 'Matcha Pokémon', 1, 11, 'Supposedly, the regrets of a tea ceremony master who died before perfecting his craft lingered in some matcha and became a Pokémon.', null, null),
  (1013, 'Sinistcha', 9, 'grass', 'ghost', 'Matcha Pokémon', 2, 22, 'It pretends to be tea, trying to fool people into drinking it so it can drain their life-force. Its ruse is generally unsuccessful.', 1012, 'Unremarkable Teacup'),
  (1014, 'Okidogi', 9, 'poison', 'fighting', 'Retainer Pokémon', 18, 922, 'After all its muscles were stimulated by the toxic chain around its neck, Okidogi transformed and gained a powerful physique.', null, null),
  (1015, 'Munkidori', 9, 'poison', 'psychic', 'Retainer Pokémon', 10, 122, 'The chain is made from toxins that enhance capabilities. It stimulated Munkidori''s brain and caused the Pokémon''s psychic powers to bloom.', null, null),
  (1016, 'Fezandipiti', 9, 'poison', 'fairy', 'Retainer Pokémon', 14, 301, 'Fezandipiti owes its beautiful looks and lovely voice to the toxic stimulants emanating from the chain wrapped around its body.', null, null),
  (1017, 'Ogerpon', 9, 'grass', null, 'Mask Pokémon', 12, 398, 'This Pokémon''s type changes based on which mask it''s wearing. It confounds its enemies with nimble movements and kicks.', null, null),
  (1018, 'Archaludon', 9, 'steel', 'dragon', 'Alloy Pokémon', 20, 600, 'It gathers static electricity from its surroundings. The beams it launches when down on all fours are tremendously powerful.', 884, 'Metal Alloy'),
  (1019, 'Hydrapple', 9, 'grass', 'dragon', 'Apple Hydra Pokémon', 18, 930, 'Seven syrpents live inside an apple made of syrup. The syrpent in the center is the commander.', 1011, 'Level up knowing Dragon Cheer'),
  (1020, 'Gouging Fire', 9, 'fire', 'dragon', 'Paradox Pokémon', 35, 5900, 'There are scant few reports of this creature being sighted. One short video shows it rampaging and spouting pillars of flame.', null, null),
  (1021, 'Raging Bolt', 9, 'electric', 'dragon', 'Paradox Pokémon', 52, 4800, 'It''s said to incinerate everything around it with lightning launched from its fur. Very little is known about this creature.', null, null),
  (1022, 'Iron Boulder', 9, 'rock', 'psychic', 'Paradox Pokémon', 15, 1625, 'It resembles a Pokémon described in a dubious magazine as a Terrakion that had been modified by an evil organization.', null, null),
  (1023, 'Iron Crown', 9, 'steel', 'psychic', 'Paradox Pokémon', 16, 1560, 'It resembles a mysterious object introduced in a paranormal magazine as a cutting-edge weapon shaped like a Cobalion.', null, null),
  (1024, 'Terapagos', 9, 'normal', null, 'Tera Pokémon', 2, 65, 'Terapagos protects itself using its power to transform energy into hard crystals. This Pokémon is the source of the Terastal phenomenon.', null, null),
  (1025, 'Pecharunt', 9, 'poison', 'ghost', 'Subjugation Pokémon', 3, 3, 'It feeds others toxic mochi that draw out desires and capabilities. Those who eat the mochi fall under Pecharunt’s control, chained to its will.', null, null);

-- Older Pokémon whose pre-evolution is new here.
update pokemon set evolves_from_id = 440, evolution_method = 'Level up holding Oval Stone (day)' where id = 113;
update pokemon set evolves_from_id = 439, evolution_method = 'Level up knowing Mimic' where id = 122;
update pokemon set evolves_from_id = 446, evolution_method = 'Friendship' where id = 143;
update pokemon set evolves_from_id = 298, evolution_method = 'Friendship' where id = 183;
update pokemon set evolves_from_id = 438, evolution_method = 'Level up knowing Mimic' where id = 185;
update pokemon set evolves_from_id = 360, evolution_method = 'Level 15' where id = 202;
update pokemon set evolves_from_id = 458, evolution_method = 'Level up with Remoraid in the party' where id = 226;
